"""Expanded original Level 2 textbook and independently authored exercises."""
import json
from pathlib import Path
root=Path(__file__).parent
d=json.loads((root/'content.json').read_text())
F='재무회계';C='원가회계'
def add(title,terms,sections,steps,problem,answer,trap,qa):
 lid=len(d['lessons'])+1
 book=dict(terms=[dict(word=w,meaning=m) for w,m in terms],sections=[dict(title=t,paragraphs=p.split('\n')) for t,p in sections],worked=dict(prompt=problem,steps=steps,choices=[answer],correct=0),bridge=trap)
 d['lessons'].append(dict(id=lid,title=title,subject=F,intro=sections[0][1].split('\n')[0],rules=[x[1] for x in terms[:3]],example=problem+' '+answer,trap=trap,book=book))
 for n,(w,m) in enumerate(terms):
  d['questions'].append(dict(id=f'{lid:02}-B{n+1}',lesson=lid,subject=F,level='입문',kind='자체 제작',prompt=f'‘{w}’의 뜻으로 알맞은 것은?',choices=[m]+[v for k,v in terms if k!=w],correct=0,explanation=f'{w}: {m} 본문의 사례에 이 뜻을 연결해봐.'))
 for n,(q,a,wrong,e) in enumerate(qa):
  d['questions'].append(dict(id=f'{lid:02}-A{n+1}',lesson=lid,subject=F,level='응용',kind='자체 제작',prompt=q,choices=[a]+wrong,correct=0,explanation=e))

add('재무회계 개념체계와 보고 원칙',[
('목적적합성','예측이나 확인에 도움을 주어 이용자의 의사결정에 차이를 줄 수 있는 정보의 특성.'),('충실한 표현','경제적 현상을 완전하고 중립적이며 오류 없이 표현하는 특성.'),('계속기업','기업이 예측 가능한 미래에도 영업을 계속한다는 재무제표 작성의 기본 가정.'),('중요성','정보를 누락·왜곡하거나 불분명하게 하면 이용자의 판단에 영향을 줄 수 있는 정도.')],[
('보고서에는 목적이 있어','회계 보고서는 숫자를 많이 모으는 것 자체가 목적은 아니야. 투자자와 대여자 등 자원을 제공하는 이용자가 회사의 미래 현금흐름과 경영진의 자원 관리에 관해 판단할 수 있도록 정보를 제공해.\n개념체계는 개별 거래의 모든 분개를 정한 규칙집이 아니라, 재무보고의 목적과 기본 개념을 연결한 틀이야. 특정 회계기준과 충돌할 때 개념체계를 이유로 그 기준을 무시하지 않아.'),
('유용한 정보의 두 가지 기둥','목적적합성은 판단에 도움이 되는지, 충실한 표현은 경제적 내용을 제대로 보여주는지를 뜻해. 예측가치는 미래를 예상하는 데, 확인가치는 과거의 예측을 점검하는 데 도움이 된다는 의미야.\n충실한 표현은 완전성·중립성·오류 없음으로 생각해. 추정치라고 무조건 오류 있는 정보는 아니야. 추정의 성격과 한계를 밝히고 적절한 방법을 정확히 적용했다면 유용한 정보가 될 수 있어.'),
('비교·검증·적시·이해를 더해','비교가능성은 회사끼리 또는 기간끼리 같은 점과 다른 점을 알아볼 수 있게 해주는 특성이야. 검증가능성은 독립적인 관찰자들이 표현의 충실성에 대체로 합의할 수 있는지를 뜻해.\n적시성은 판단에 도움이 될 때 정보가 제공되는 것이고, 이해가능성은 명확하고 간결하게 분류·표시하는 것이야. 어려운 내용이라고 필요한 정보를 아예 빼는 뜻은 아니야. 이 네 가지는 근본적 특성을 보강해.'),
('인식과 측정은 다른 질문이야','인식은 자산·부채·수익·비용 등을 재무제표에 포함시키는 것이고, 측정은 얼마로 적을지 정하는 거야. 먼저 정의와 인식 요건을 판단한 다음 측정 기준을 적용해.\n역사적 원가는 거래 당시의 원가에서 출발하고, 현행가치에는 공정가치·사용가치 등 현재의 정보를 반영하는 측정이 있어. 모든 자산을 언제나 시장가격으로 적는 것은 아니므로 해당 계정의 기준을 확인해.'),
('계속기업과 발생기준','회사가 계속 운영된다고 보고 기계의 사용기간에 걸쳐 감가상각하는 것은 계속기업 가정과 연결돼. 청산을 전제로 작성해야 한다면 사용하는 측정과 표시가 달라질 수 있어.\n발생기준은 현금이 오간 날만 보지 않고 거래 효과가 발생한 기간에 반영해. 비교표시·일관된 분류·중요한 항목의 구분도 정보를 이해하게 돕는 원칙이야. 서로 다른 자산과 부채를 허용 근거 없이 마음대로 상계하지 않아.'),
('유동과 비유동을 구분해','정상영업주기 안에서 실현·판매·소비될 자산, 단기매매 목적 자산, 보고기간 후 12개월 이내 실현할 자산, 일정 제한이 없는 현금·현금성자산 등을 유동자산으로 분류해. 나머지는 비유동자산이야.\n부채도 정상영업주기, 매매 목적, 12개월 내 결제 여부와 보고일 현재 결제를 최소 12개월 연기할 권리 등을 판단해. “1년만 보면 끝”이라고 외우면 영업주기가 긴 재고·매입채무에서 틀릴 수 있어.')],
['정보가 미래 예상이나 과거 판단의 확인에 도움이 되는지를 봐.','그 내용이 완전하고 중립적으로 적절하게 표현됐는지 봐.','같은 분류와 정책을 확인해 회사·기간 사이의 차이를 비교해.'],
'작년과 올해의 매출을 비교하려고 해. 올해만 매출과 관계없는 대출금을 매출에 더했다면 왜 문제가 될까?',
'대출은 매출이 아니므로 경제적 내용을 충실하게 표현하지 못하고 기간 비교도 왜곡돼.',
'목적적합성·충실한 표현은 근본적 특성, 비교·검증·적시·이해가능성은 보강적 특성이야.',[
('유용한 재무정보의 근본적 질적 특성 두 가지는?','목적적합성과 충실한 표현',['비교가능성과 적시성','검증가능성과 이해가능성','계속기업과 현금주의'],'비교·검증·적시·이해가능성은 보강적 특성이야.'),
('정상영업주기가 18개월이고 그 주기 안에 판매될 재고는 원칙적으로?','유동자산',['무조건 비유동자산','부채','자본'],'정상영업주기 안의 판매·소비 여부가 유동분류의 기준 중 하나야.'),
('거래를 재무제표에 포함할지 결정한 뒤 얼마로 적을지 정하는 작업은?','측정',['상계','배당','전기'],'인식은 포함 여부, 측정은 금액의 결정이야.'),
('회계추정치라는 이유만으로 충실한 표현이 될 수 없다는 주장은?','틀리다',['항상 옳다','현금만 해당한다','비유동자산만 옳다'],'추정 과정과 불확실성이 적절히 설명되고 방법이 오류 없이 적용될 수 있어.')])

add('고객과의 계약과 수익인식',[
('수행의무','고객에게 구별되는 재화나 용역을 이전하기로 한 약속.'),('거래가격','약속한 재화·용역을 이전하고 받을 것으로 예상하는 대가.'),('계약부채','대가를 먼저 받았거나 지급기일이 됐지만 고객에게 재화·용역을 이전할 의무가 남은 금액.'),('통제','자산의 사용을 지시하고 나머지 효익의 대부분을 얻을 수 있는 능력.')],[
('대금을 받는 것과 약속을 이행하는 것','손님이 수업료를 먼저 냈어도 아직 수업을 하지 않았다면 회사에는 가르칠 의무가 남아 있어. 수익은 약속한 재화나 용역을 고객에게 이전해 수행의무를 이행할 때 인식하는 것이 중심 원리야.\n단순 판매에서 상품의 통제가 넘어가는 시점과 돈이 들어오는 시점은 다를 수 있어. 계약조건, 인도와 검수, 고객의 권리를 읽어야 해.'),
('다섯 단계를 순서대로 적용해','① 고객과의 계약 식별 ② 수행의무 식별 ③ 거래가격 산정 ④ 거래가격을 수행의무에 배분 ⑤ 수행의무를 이행할 때 수익 인식이야. 무엇을 약속했고 얼마를 받을지부터 정리하는 순서라고 생각해.\n기계와 별도 유지보수 서비스를 묶어 팔았다면 두 약속이 구별되는지 판단해. 구별되는 수행의무라면 기계 인도 때 계약 전체 금액을 수익으로 적지 않고 각각에 배분해.'),
('묶음 가격은 개별 판매가격 비율로 나눠','기계의 개별 판매가격 80, 유지보수의 개별 판매가격 20인 두 수행의무를 90에 계약했다고 하자. 일반적인 비례배분이면 기계 90×80/100=72, 유지보수 90×20/100=18이야.\n기계를 인도하고 유지보수는 아직 시작하지 않았다면 기계의 72만 인식하고 나머지는 수행할 때 인식해. 할인이나 변동대가를 특정 의무에 배분하는 별도 요건이 주어지면 그 조건을 따라야 해.'),
('기간에 걸쳐 인식하는 경우','고객이 수행과 동시에 효익을 얻고 소비하는 서비스 등 일정 요건에 해당하면 기간에 걸쳐 수익을 인식해. 단지 계약기간이 길다는 이유만으로 모두 기간 기준이 되는 것은 아니야.\n투입원가가 수행 정도를 충실하게 보여주고 원가기준 진행률이 적절하다는 조건이면 누적 실제원가÷예상 총원가로 진행률을 구할 수 있어. 당기수익은 누적수익에서 이전 기간까지 인식한 수익을 빼야 해.'),
('반품·할인·변동대가','반품이 예상되면 반품될 대가까지 모두 수익으로 잡지 않아. 환불부채와 반환받을 제품에 대한 권리도 검토해. 변동대가는 나중에 유의적으로 환원되지 않을 가능성이 매우 높은 범위라는 제약을 적용해.\n현금할인, 판매장려금처럼 대가를 줄이는 조건과 단순 대손을 구분해. 고객이 처음부터 지급할 가격의 문제인지, 확정된 채권을 회수하지 못할 위험인지에 따라 회계처리가 달라져.'),
('본인과 대리인·채권과 계약자산','회사가 고객에게 이전하기 전 재화·용역을 통제하는 본인이라면 총액 수익, 다른 기업의 제공을 주선하는 대리인이라면 수수료 등 순액 수익을 생각해. 통장으로 전체 대금이 들어왔다는 사실만으로 본인은 아니야.\n대가를 받을 권리가 시간 경과만 남은 무조건적 권리라면 수취채권이야. 다른 수행 등 조건이 붙은 권리는 계약자산일 수 있어. 계약부채는 받을 권리가 아니라 앞으로 이전할 의무라는 점을 구분해.')],
['전체 개별 판매가격은 80+20=100이야.','기계 배분액 90×80/100=72, 유지보수 배분액 90×20/100=18이야.','기계만 인도했다면 수익 72, 아직 수행하지 않은 유지보수 몫 18은 남겨.'],
'기계 80, 1년 유지보수 20을 묶어 90에 선납받았어. 구별되는 수행의무이고 할인은 비례배분해. 기계만 인도한 시점의 수익은?',
'72. 배분된 유지보수 대금 18은 아직 수익으로 인식하지 않아.',
'누적 진행률로 계산한 금액과 당기 수익을 구분해. 부가가치세 등 제삼자를 대신해 받은 금액은 수익에 포함하지 않아.',[
('개별가격 A 60, B 40인 별도 의무를 총 80에 팔았다. 비례배분한 A의 대가는?','48',['60','40','32'],'80×60/(60+40)=48이야.'),
('총계약수익 1,000, 적절한 원가기준 진행률 40%, 전기까지 인식한 수익 150. 당기수익은?','250',['400','150','550'],'누적 1,000×40%=400에서 전기 150을 빼 250이야.'),
('아직 서비스를 제공하지 않고 받은 선수대금의 기본 분류는?','계약부채',['즉시 전액 수익','금융자산 평가이익','자본금'],'고객에게 서비스를 제공할 의무가 남아 있어.'),
('대리인으로 상품대금 100을 받아 공급자에게 92를 전달하고 수수료 8을 받았다. 수익은?','8',['100','92','108'],'대리인의 수익은 자신의 수수료 몫이야.')])

add('재고자산의 수량·단가·평가',[
('순실현가능가치','예상 판매가격에서 완성에 필요한 원가와 판매에 필요한 원가를 뺀 금액.'),('계속기록법','매입·매출 때마다 재고의 증감을 장부에 기록하는 방법.'),('실지재고조사법','기말 실사 재고 등을 바탕으로 판매된 수량·원가를 계산하는 방법.'),('이동평균법','매입이 생길 때마다 보유재고의 평균단가를 다시 계산하는 방법.')],[
('무엇을 재고로 포함할까?','판매할 상품과 제품, 생산 중인 재공품, 생산에 사용할 원재료가 재고자산이야. 사무실에서 몇 년 쓸 책상은 보통 유형자산으로 보고 판매할 책상과 구분해.\n기말에는 창고에 있다는 이유만으로 우리 재고인지 결정하지 않아. 위탁판매를 위해 맡긴 재고는 일반적으로 위탁자의 재고이고, 운송 중인 미착품은 통제 이전 조건을 확인해야 해.'),
('취득원가에는 필요한 원가를 더해','매입가격에서 매입할인·리베이트 등을 빼고, 운송료·취급원가·환급되지 않는 세금처럼 현재 장소와 상태로 가져오는 원가를 더해. 환급받을 수 있는 부가가치세는 재고원가에서 제외해.\n비정상 낭비, 통상적인 판매비, 생산에 필요하지 않은 보관원가 등을 무조건 재고에 넣지 않아. 제조 재고에는 직접원가와 적절히 배분한 제조간접원가가 포함될 수 있어.'),
('장부 기록과 실사 수량','계속기록법에서는 판매 때 판매수익 기록과 함께 매출원가·재고 감소를 기록해. 실지재고조사법에서는 기말 실사 등을 통해 판매원가를 확정해.\n기초재고+순매입=판매가능재고이고, 여기에 기말재고를 빼면 단순 사례의 매출원가야. 도난·감모가 있으면 실사 차이와 원인을 따로 확인해. 매출액을 빼는 식이 아니야.'),
('선입선출법과 평균법','선입선출법은 먼저 산 원가부터 판매원가에 배분한다고 가정해. 물건이 실제 어느 순서로 나갔는지와 원가배분의 가정은 구분해야 해. 기말재고에는 최근 단가가 남아.\n총평균법은 기간의 총원가를 총수량으로 나누고, 이동평균법은 매입 때마다 평균을 바꿔. 매입과 매출이 교차하면 두 평균법 결과가 달라질 수 있어. 후입선출법은 K-IFRS의 허용 원가공식이 아니야.'),
('낮아진 가치는 어떻게 반영해?','재고는 원가와 순실현가능가치 중 낮은 금액으로 평가해. 원가 100, 예상 판매가격 95, 추가완성원가 3, 판매원가 2라면 순실현가능가치 90이므로 10을 평가감액해.\n나중에 가치가 회복되면 종전 감액을 한도로 환입할 수 있어. 회복했다고 원래 원가보다 높게 재고를 올리는 것은 아니야. 정상 감모와 비정상 감모는 문제의 원인·처리 조건을 구분해.'),
('재고 오류가 손익에 미치는 방향','기말재고를 실제보다 크게 적으면 매출원가가 작아져 당기이익과 자산이 크게 표시돼. 다음 해 기초재고가 그대로 넘어가면 다음 해의 매출원가는 반대로 커질 수 있어.\n방향이 헷갈리면 매출원가=기초+매입−기말 식에 숫자를 넣어. 기말에 빼는 금액이 커지면 계산 결과가 작아진다는 점을 확인하면 돼.')],
['먼저 산 10개×1,000원=10,000원을 판매원가에 배분해.','12개 판매 중 나머지 2개는 최근 단가 1,500원으로 계산해 3,000원이야.','매출원가 13,000원, 남은 8개×1,500원=기말재고 12,000원. 둘의 합은 매입원가 25,000원이야.'],
'기초재고 없이 10개를 개당 1,000원, 이어 10개를 1,500원에 샀어. 모두 매입한 뒤 12개를 팔았을 때 선입선출법 매출원가와 기말재고는?',
'매출원가 13,000원 / 기말재고 12,000원.',
'원가배분 방법, 재고 기록방법, 저가평가는 서로 다른 질문이야. 먼저 수량을 맞추고 단가와 평가를 적용해.',[
('10개×1,000원과 10개×1,500원을 모두 매입한 뒤 12개 판매. 총평균법 기말재고는?','10,000원',['12,000원','15,000원','8,000원'],'평균단가 25,000÷20=1,250원, 남은 8개×1,250=10,000원이야.'),
('재고 원가 200, 예상판매가 190, 완성·판매원가 합계 15. 평가액은?','175',['200','190','185'],'순실현가능가치 190−15=175와 원가 200 중 낮은 175야.'),
('기말재고를 30 과대계상하면 다른 조건이 같을 때 당기 매출원가는?','30 과소계상',['30 과대계상','변동 없음','60 과대계상'],'매출원가=기초+매입−기말이므로 기말을 크게 빼면 원가가 작아져.'),
('회사 창고에 보관 중인 타사의 위탁상품은 원칙적으로?','위탁한 타사의 재고',['보관회사의 재고','양사 모두 재고','항상 비용'],'물리적 보관 장소와 자산의 통제·소유 관계를 구분해야 해.')])

add('유형자산의 취득·감가상각·손상',[
('취득원가','자산을 의도한 방식으로 가동할 장소와 상태에 이르게 하는 데 필요한 원가.'),('감가상각대상금액','취득원가 등 원가대체금액에서 잔존가치를 뺀 금액.'),('회수가능액','처분부대원가를 뺀 공정가치와 사용가치 중 큰 금액.'),('장부금액','원가 등에서 감가상각누계액과 손상차손누계액을 차감한 금액.')],[
('기계를 사 오는 비용부터 모아','기계 가격뿐 아니라 배송·설치·시운전 등 사용 가능한 상태로 만드는 직접 관련 원가를 포함해. 할인을 빼고, 복구의무가 있다면 요건에 따라 미래 복구원가의 현재가치를 취득원가와 부채에 반영해.\n직원 교육비, 개업비, 새로운 시설의 초기 영업손실은 자산 취득원가로 무조건 넣지 않아. 정상 가동 전 생산한 제품의 판매대금을 기계 원가에서 임의로 차감하는 것도 피해야 해.'),
('수선과 성능 개선을 구분해','일상적인 수선·유지는 일반적으로 발생한 기간의 비용이야. 반면 미래 효익이 기대되고 원가를 신뢰성 있게 측정하는 등 인식 요건을 충족한 교체·개선은 자산 원가에 포함할 수 있어.\n단순히 금액이 크다는 이유가 아니라 효익과 인식 요건을 따져. 중요 부품을 교체하면 새 부품을 인식하는 것과 함께 기존 부품의 장부금액 제거도 고려해.'),
('정액법·정률법·생산량비례법','정액법은 (원가−잔존가치)÷내용연수로 같은 금액을 배분해. 정률법은 기초 장부금액에 일정 비율을 적용해 초기에 더 큰 비용이 생기는 방식이야.\n생산량비례법은 감가상각대상금액×당기 생산량÷예상 총생산량으로 계산해. 자산의 효익 소비 형태에 맞는 방법을 써. 수익에 근거한 감가상각 방법은 적절하지 않아.'),
('시작 시점과 기간을 확인해','감가상각은 자산이 사용 가능한 때부터 시작해. 구입일과 사용가능일이 다르면 문제의 조건을 확인해야 해. 연간 상각액을 계산한 뒤 필요한 월수나 기간 비율을 곱해.\n토지는 일반적으로 내용연수가 한정되지 않아 상각하지 않고, 건물은 상각해. 자산을 잠시 놀린다는 이유만으로 감가상각을 항상 멈추는 것도 아니야.'),
('손상과 재평가는 다르게 봐','회수가능액은 ① 팔 때 받을 공정가치에서 처분부대원가를 뺀 금액과 ② 계속 사용해 얻을 미래 현금흐름의 현재가치인 사용가치 중 큰 금액이야. 장부금액 500, 처분부대원가 차감 후 공정가치 420, 사용가치 450이라면 회수가능액 450과 비교해 손상차손 50을 인식해.\n재평가모형의 증가는 일반적으로 기타포괄손익·재평가잉여금, 감소는 일반적으로 당기손익이지만 같은 자산의 과거 재평가 기록에 따라 상계되는 부분이 있어. 원가모형인지 재평가모형인지부터 읽어.'),
('처분 전에는 처분일까지 상각해','기계를 팔 때 먼저 처분일까지의 감가상각을 반영하고 장부금액을 구해. 순처분대가에서 장부금액을 빼면 처분손익이야. 원래 구입가격과 매각대금을 바로 비교하지 않아.\n분개에서는 현금 등 받은 대가와 감가상각누계액을 반영하고 기계 원가를 제거해. 차액이 이익이면 대변, 손실이면 차변에 들어가.')],
['원가 1,000−잔존가치 100=상각대상 900, 연간 정액상각액은 900÷5=180이야.','2년 사용 후 장부금액은 1,000−180×2=640이야.','처분대가 700−장부금액 640=처분이익 60이야.'],
'원가 1,000, 잔존가치 100, 내용연수 5년인 기계를 정액법으로 정확히 2년 사용하고 700에 팔았어. 손상·부대원가는 없을 때 처분손익은?',
'유형자산처분이익 60.',
'잔존가치는 정액법 계산에서 먼저 빼고, 장부금액 계산에서는 감가상각누계액을 원가에서 빼. 이 두 식을 섞지 마.',[
('원가 600, 잔존가치 60, 내용연수 3년. 7월 1일 사용 가능, 12월 말 결산. 월할 정액상각액은?','90',['180','100','200'],'연간 (600−60)÷3=180, 6개월분 180×6/12=90이야.'),
('장부금액 500, 처분부대원가 차감 공정가치 420, 사용가치 460. 손상차손은?','40',['80','0','460'],'회수가능액=max(420,460)=460. 500−460=40이야.'),
('기계의 일상적 청소·수선 지출의 일반적인 처리는?','당기 비용',['항상 토지원가','항상 자본금','항상 영구 자산'],'일상 유지비는 일반적으로 발생 시 비용이야.'),
('기초 장부금액 800, 정률 25%, 잔존가치 하한에 닿지 않는다. 당기 상각액은?','200',['600','25','100'],'기초 장부금액 800×25%=200이야.')])

add('투자부동산·무형자산·연구개발',[
('투자부동산','임대수익이나 시세차익 또는 둘 다를 목적으로 보유하는 부동산.'),('무형자산','물리적 실체가 없는 식별가능한 비화폐성 자산.'),('연구단계','새로운 과학적·기술적 지식과 이해를 얻기 위한 독창적이고 계획적인 조사 단계.'),('비한정 내용연수','관련 요소를 분석해도 순현금유입이 발생할 기간에 예측가능한 제한이 없는 경우.')],[
('같은 건물도 사용 목적이 달라','직접 사무실로 사용하는 건물은 자가사용 유형자산, 임대수익이나 시세차익을 얻으려고 보유하는 건물은 투자부동산을 생각해. 통상적인 영업 과정에서 판매하려는 부동산은 재고자산이 될 수 있어.\n명칭에 “투자”가 붙었는지보다 실제 사용 목적과 상황을 봐. 복합 사용 건물은 부분별 분리가 가능한지와 자가사용 비중 등 별도 조건을 검토해.'),
('투자부동산의 후속 측정','원가모형에서는 감가상각·손상 등을 반영해 장부금액을 계산해. 공정가치모형에서는 보고일 공정가치로 측정하고 변동을 당기손익에 반영해.\n공정가치모형의 투자부동산에는 감가상각을 별도로 적용하지 않아. 유형자산 재평가모형의 기타포괄손익 처리와 혼동하지 않는 게 중요해.'),
('무형자산은 식별가능해야 해','특허권·소프트웨어·저작권처럼 형태가 없어도 식별되고 회사가 통제하며 미래 효익이 기대되는 자원을 생각해. 식별가능성은 분리하여 이전할 수 있거나 계약상·법적 권리에서 생기는지 등으로 판단해.\n직원들의 능력이나 내부에서 만들어진 평판을 소중하게 여긴다고 모두 무형자산으로 적을 수는 없어. 내부창출 영업권은 자산으로 인식하지 않아.'),
('연구는 비용, 개발은 요건을 모두 확인해','연구 지출은 발생 시 비용으로 처리해. 개발 지출은 기술적 실현가능성, 완성·사용·판매 의도와 능력, 미래 효익, 충분한 자원, 원가의 신뢰성 있는 측정 등 요건을 모두 입증할 수 있을 때부터 자산화해.\n앞서 비용으로 처리한 연구·개발 지출을 나중에 성공했다는 이유로 되돌려 자산에 넣지 않아. 어느 날짜부터 요건을 충족했는지 문제의 문장을 읽어.'),
('상각과 손상검사','내용연수가 유한한 무형자산은 사용 가능할 때부터 그 기간에 걸쳐 상각해. 잔존가치는 일반적으로 0으로 보지만 제삼자의 매입약정 등 예외 조건이 있으면 확인해.\n비한정 내용연수의 무형자산은 상각하지 않고 매년 및 손상징후가 있을 때 손상검사를 해. 비한정은 “절대 영원하다”는 뜻이 아니므로 판단을 재검토해야 해.'),
('구입한 영업권은 별도로 이해해','사업결합에서 인식하는 영업권은 특정 권리 하나가 아니라 개별 식별되지 않는 미래 효익과 연결돼. 내부창출 영업권과 사업결합에서 취득한 영업권을 구분해.\nK-IFRS의 영업권은 상각하지 않고 손상을 검토하며 영업권 손상차손은 환입하지 않아. 일반 무형자산의 상각·손상 규칙을 모두 동일하게 적용하지 않아.')],
['연구단계 30은 비용이야.','개발요건을 충족하기 전 지출 20도 비용으로 남아.','요건을 충족한 이후의 개발원가 50만 자산으로 인식해.'],
'연구 30, 개발요건 충족 전 지출 20, 모든 요건 충족 후 직접 개발지출 50이 발생했어. 상각 전 개발비 자산과 당기비용은?',
'개발비 자산 50 / 당기비용 50.',
'투자부동산 공정가치 변동은 당기손익, 유형자산 재평가 증가는 일반적으로 기타포괄손익이라는 차이를 기억해.',[
('공정가치모형 투자부동산이 500에서 540으로 상승했다. 변동액의 처리는?','당기이익 40',['기타포괄이익 40만','감가상각비 40','아무 기록 없음'],'투자부동산 공정가치모형의 변동은 당기손익에 반영해.'),
('비한정 내용연수 무형자산의 기본 후속 처리는?','상각 없이 매년 손상검사',['무조건 5년 상각','매년 전액 비용','손상도 상각도 없음'],'상각은 하지 않지만 매년 손상검사가 필요해.'),
('이미 비용 처리한 연구 지출이 나중에 개발 성공으로 회수될 전망이다. 과거 지출은?','비용 처리를 유지',['무조건 개발비로 소급 인식','자본금으로 변경','재고자산으로 변경'],'과거 비용을 이후의 성공만으로 무형자산으로 되돌리지 않아.'),
('특허권 원가 120, 잔존 0, 유한 내용연수 6년, 1년 정액상각. 상각액은?','20',['120','6','0'],'120÷6=20이야. 비한정 내용연수 사례와 구분해.')])

add('유동부채·충당부채·우발사항',[
('매입채무','통상적인 영업거래에서 재화·용역을 외상 매입하여 지급할 채무.'),('충당부채','지급시기나 금액이 불확실한 부채.'),('우발부채','가능한 의무이거나 현재의무지만 유출 가능성·측정 요건 때문에 인식하지 않는 의무.'),('최선의 추정치','보고기간 말 현재의무를 이행하는 데 필요한 지출에 대한 가장 적절한 추정 금액.')],[
('채무는 생긴 이유에 따라 이름이 달라','판매할 상품을 외상으로 사면 매입채무, 기계를 외상으로 사면 미지급금, 이미 발생한 이자를 아직 지급하지 않았다면 미지급비용을 생각할 수 있어. 모두 지급할 의무이지만 거래 성격이 달라.\n손님에게 대금을 미리 받았다면 앞으로 상품이나 서비스를 제공할 의무가 생겨 선수금·계약부채 등으로 기록해. 돈을 받았다는 사실만으로 수익은 아니야.'),
('충당부채를 인식하는 세 조건','과거 사건으로 현재의무가 존재하고, 의무 이행을 위해 경제적 자원이 유출될 가능성이 높고, 금액을 신뢰성 있게 추정할 수 있을 때 충당부채를 인식해. 법적 의무뿐 아니라 의제의무도 검토해.\n의제의무는 회사의 관행이나 구체적 발표 등으로 상대방에게 책임을 이행할 것이라는 정당한 기대를 형성한 경우를 말해. 막연한 미래 지출 계획만으로 충당부채를 만들지는 않아.'),
('보증수리 비용을 예상해','제품을 팔면서 정상적인 품질을 보증해 판매 시점에 보증의무가 생겼다면, 예상 수리원가를 충당부채로 인식할 수 있어. 여러 제품으로 구성된 집단은 확률별 금액을 가중한 기대값이 유용해.\n실제로 수리하면 이미 설정한 충당부채를 사용해. 예상비용을 설정할 때와 지급할 때 비용을 중복 인식하지 않도록 조심해. 별도로 판매하는 서비스 보증은 수익인식 기준에 따른 수행의무일 수 있어.'),
('우발부채는 인식과 공시를 구분해','자원 유출 가능성이 높지 않거나 신뢰성 있는 측정이 불가능하여 인식 요건을 충족하지 못한 의무 등은 우발부채일 수 있어. 일반적으로 재무상태표에 부채로 인식하지 않지만 주석 공시 여부를 검토해.\n유출 가능성이 아주 낮다면 공시하지 않는 경우도 있어. 우발자산도 이익을 성급하게 인식하지 않아. 경제적 효익 유입이 거의 확실해져 더 이상 우발적이지 않다면 자산 인식을 검토해.'),
('할인과 추정 변경','화폐의 시간가치 영향이 중요하면 예상 지출을 현재가치로 할인해 측정해. 시간이 지나 결제일이 가까워지면서 할인액이 풀리는 효과도 반영해.\n매 보고일 추정치를 재검토하고 필요한 금액으로 조정해. 의무를 갚을 가능성이 더 이상 높지 않으면 충당부채를 환입해. 처음 설정한 특정 의무와 무관한 지출을 처리하는 통처럼 사용하면 안 돼.'),
('장기차입금의 유동성 대체','장기차입금 중 보고일 현재 12개월 내 갚아야 하는 부분 등은 유동성장기부채로 분류될 수 있어. 원금 전체를 비유동으로 남겨 놓지 말고 만기와 보고일 현재의 권리를 봐.\n차입약정 위반이나 차환 약정은 시점과 조건에 따라 분류에 영향을 줘. 기초 문제에서는 제시된 만기·분할상환액을 정리하고, 수익이나 비용이 아니라 부채 안의 표시 변경이라는 점부터 이해해.')],
['수리 없음 80%의 지출은 0이야.','소액수리 15%×100=15, 큰 수리 5%×400=20이야.','제품집단의 기대 지출은 0+15+20=35이므로 해당 조건에서 충당부채 35를 인식해.'],
'판매한 제품집단에서 수리 없음 80%, 소액수리 총원가 100 발생 가능성 15%, 큰 수리 총원가 400 가능성 5%야. 기대값 기준 보증충당부채는?',
'35. 이는 실제 지급액이 아니라 보고일 현재의 추정 의무야.',
'충당부채와 대손충당금은 달라. 전자는 부채, 후자는 채권을 줄이는 평가 항목이야.',[
('현재의무·높은 유출가능성·신뢰성 있는 추정이 모두 충족되는 소송의무는?','충당부채 인식',['무조건 무시','자본금 인식','수익 인식'],'세 인식 요건이 충족되므로 최선의 추정치로 인식해.'),
('내년에 새 공장을 지으려는 단순 계획만 있다. 현재의무가 없을 때 충당부채는?','인식하지 않는다',['예산 전액 인식','예산 절반 인식','항상 우발자산 인식'],'미래 투자 계획만으로 현재의무가 발생하지 않아.'),
('이미 설정한 보증충당부채로 수리비 10을 지급했다. 기본 차변 계정은?','보증충당부채',['자본금','매출','대손충당금'],'기존 의무를 이행했으므로 충당부채를 줄이고 현금을 줄여.'),
('만기상환 3년인 차입금 500 중 보고일 후 6개월에 상환할 100이 별도로 있다. 다른 조건 없을 때 유동성 부분은?','100',['500','400','0'],'12개월 내 상환 부분 100을 유동성 부채로 구분해.')])

add('종업원급여와 퇴직급여',[
('단기종업원급여','근로가 제공된 연차보고기간 말부터 12개월 이전에 전부 결제될 것으로 예상되는 급여.'),('확정기여제도','회사가 정해진 기여금을 별도 기금에 내고 추가 납부의무를 부담하지 않는 퇴직급여제도.'),('확정급여제도','확정기여제도 이외의 퇴직급여제도. 약속한 급여와 관련한 위험을 기업이 부담할 수 있어.'),('사외적립자산','퇴직급여 지급 등을 위해 기업과 별도로 적립되어 요건을 충족하는 자산.')],[
('급여도 발생한 기간을 맞춰','직원이 12월에 일하고 월급은 1월에 받더라도 회사가 근로를 제공받은 12월의 급여를 인식해. 단기급여는 일반적으로 할인하지 않은 금액으로 측정해.\n급여가 항상 판매관리비만 되는 것은 아니야. 생산직 근로처럼 재고자산 제조에 직접 관련된다면 다른 기준에 따라 자산 원가에 포함될 수 있어. 직원의 업무와 문제 조건을 함께 봐.'),
('실수령액과 회사의 급여비용','급여 총액 300에서 원천징수액 등 30을 공제하고 직원에게 270을 줬다면 급여 총액은 300이야. 회사가 잠시 보관했다가 납부할 30은 예수금 등 의무로 구분해.\n직원 통장에 들어간 270만 비용이라고 적으면 총액을 빠뜨리게 돼. 사용자 부담 사회보험료는 직원에게서 공제한 금액과 별도로 회사 부담 원가를 검토해.'),
('연차·상여금·이익분배','근로 제공에 따라 누적되는 유급휴가의 의무, 지급할 현재의무가 있고 신뢰성 있게 추정할 수 있는 상여금 등을 보고일에 반영할 수 있어. 실제 지급 전이라는 이유만으로 모두 다음 해 비용은 아니야.\n누적되지 않는 휴가나 지급 조건이 다른 상여금은 인식 시점이 다를 수 있어. “누적”, “의무 발생”, “신뢰성 있는 추정” 같은 조건을 읽어야 해.'),
('확정기여형은 납부할 기여금이 중심','회사가 해당 기간 근로에 대해 부담할 기여금이 24이고 20만 냈다면, 원칙적으로 관련 비용·원가 24와 미지급 의무 4를 반영해. 기금 투자수익이 나빠졌다고 회사가 추가 부담할 의무가 없다면 확정기여형의 특징에 맞아.\n확정기여형을 “직원 퇴직할 때까지 회계처리하지 않는다”고 생각하면 안 돼. 근로를 제공받은 기간에 기여금 의무를 인식해.'),
('확정급여형은 약속한 급여를 측정해','미래 지급할 확정급여채무의 현재가치를 추정하고 사외적립자산 공정가치를 차감해 순확정급여부채 또는 자산을 계산해. 순자산에는 자산인식상한 등 제약을 검토해.\n기초 예제에서 채무 현재가치 500, 적립자산 420이면 순부채 80이야. 지급할 미래 명목액과 현재가치, 회사 장부의 순부채를 구분해.'),
('비용과 재측정요소를 나눠','확정급여의 근무원가와 순이자는 원칙적으로 당기손익에 반영하고, 보험수리적손익 등 순부채·자산의 재측정요소는 기타포괄손익으로 처리해. 다른 기준에 따른 자산 원가 포함 부분은 별도야.\n채무가 증가했다고 모든 증가액이 당기 퇴직급여비용인 것은 아니야. 기여금 납부, 급여 지급, 근무원가, 순이자, 재측정의 흐름을 나눠야 해. 기타장기급여와 해고급여는 확정급여 퇴직급여와 모든 처리가 같은 것도 아니야.')],
['급여비용은 공제 전 총액 300이야.','현금 지급은 300−30=270이고 나머지 30은 납부할 예수금이야.','차변 급여 300 / 대변 현금 270, 예수금 30으로 합계를 맞춰.'],
'당월 급여 300에서 직원 부담 공제액 30을 떼고 나머지를 현금 지급했어. 생산원가에 포함하지 않는 사무직 급여의 기본 분개는?',
'차변 급여 300 / 대변 현금 270, 예수금 30.',
'확정기여는 납부할 기여금, 확정급여는 약속한 급여의 현재가치와 적립자산을 중심으로 구분해.',[
('확정기여형 당기 기여금 36, 실제 납부 30. 기초 미지급 없음. 기말 미지급액은?','6',['36','30','66'],'발생 의무 36−납부 30=6이야.'),
('확정급여채무 현재가치 800, 사외적립자산 공정가치 650. 다른 조정이 없을 때 순부채는?','150',['800','650','1,450'],'채무 800에서 적립자산 650을 빼 150이야.'),
('확정급여제도의 보험수리적손실 등 재측정요소는 원칙적으로?','기타포괄손익',['모두 자본금','모두 매출원가','아무 기록 없음'],'근무원가·순이자와 재측정요소의 인식 위치를 구분해.'),
('급여 총액 200, 직원 부담 공제 20, 실제 지급 180. 사무직 급여비용은?','200',['180','20','220'],'직원 공제는 총급여를 줄이는 것이 아니라 지급 상대방을 나눈 것이야.')])

add('금융자산의 분류·평가·손상',[
('상각후원가','최초 금액에서 원금 회수 등을 반영하고 유효이자율법으로 할인·할증을 배분한 금액.'),('당기손익-공정가치','공정가치 변동을 당기손익으로 반영하는 측정 분류.'),('기타포괄손익-공정가치','공정가치 변동의 일정 부분을 기타포괄손익으로 반영하는 측정 분류.'),('기대신용손실','채무 불이행 위험 등을 반영해 예상하는 현금흐름 부족액의 현재가치.')],[
('현금·채권·다른 회사 주식','금융자산에는 현금, 다른 기업의 지분상품, 현금 등을 받을 계약상 권리 등이 있어. 판매할 물건인 재고자산이나 공장의 기계와 구분해.\n채무상품은 상대방이 원금·이자 등 계약상 금액을 지급하는 채권이고, 지분상품은 소유 지분이야. 회사가 발행한 사채는 발행자에게 금융부채, 그 사채를 산 투자자에게는 금융자산이 된다는 양면도 이해해.'),
('채무상품은 두 질문을 함께 해','어떻게 관리하나라는 사업모형과, 계약상 현금흐름이 원금 및 원금잔액에 대한 이자로만 구성되는가라는 조건을 함께 봐. 후자를 SPPI 조건이라고도 해.\nSPPI를 충족하고 계약상 현금흐름 수취가 목적인 경우 상각후원가, 수취와 매도가 함께 목적이면 기타포괄손익-공정가치로 분류하는 것이 기본이야. 그 밖에는 당기손익-공정가치가 원칙이며 지정 등 별도 조건이 있으면 확인해.'),
('지분상품의 선택은 채무상품과 달라','지분상품 투자는 원칙적으로 당기손익-공정가치로 측정해. 단기매매 목적 등이 아닌 적격 지분상품에는 최초 인식 때 기타포괄손익 표시를 취소할 수 없게 선택할 수 있어.\n이 선택을 한 지분상품의 처분 시 누적 기타포괄손익은 당기손익으로 재분류하지 않아. 채무상품 FVOCI의 처분 시 재분류와 다르므로 “주식인가 채권인가”부터 표시해. 적격 배당은 원칙적으로 당기손익이야.'),
('취득 수수료는 분류에 따라','금융자산은 원칙적으로 최초 공정가치로 인식해. 당기손익-공정가치 분류의 직접 거래원가는 당기비용, 그 밖의 분류에서는 원칙적으로 최초 측정에 가산해.\n가격 100, 직접 수수료 2인 단기매매 주식을 샀다면 주식 100과 비용 2를 구분해. 이와 달리 다른 요건을 충족한 상각후원가 채권은 직접 거래원가를 반영한 금액에서 유효이자율을 적용해.'),
('이자수익은 장부금액과 연결해','신용손상 등의 예외가 없는 단순 상각후원가 채권에서 유효이자수익은 기초 총장부금액×유효이자율이야. 실제 받은 표시이자와의 차이가 할인·할증 상각액이 돼.\n채권을 할인 취득하면 일반적으로 유효이자수익이 현금이자보다 커서 장부금액이 만기 원금 쪽으로 증가해. 발행자 사채의 이자비용 계산과 방향을 나란히 비교하면 이해하기 쉬워.'),
('회수위험은 기대신용손실로 반영해','매출채권은 간편법 요건에 따라 전체기간 기대신용손실을 사용하는 경우가 있어. 일반 모형은 신용위험의 유의적 증가 여부 등에 따라 12개월 또는 전체기간 기대신용손실을 구분해.\n“12개월 기대신용손실”이 곧 향후 12개월 동안의 현금부족액만 뜻하는 것은 아니야. 향후 12개월에 발생 가능한 채무불이행 사건에서 비롯된 손실을 뜻해. 기초 문제에서는 필요한 충당금 잔액과 기존 잔액의 차이를 먼저 계산해.'),
('채권 제거와 회수는 별개야','외상매출금을 회수하면 현금이 증가하고 채권이 줄어. 상각 대상 채권을 실제 제거하면 기존 충당금과 채권을 줄이는 처리를 생각해. 손실 예상 비용과 실제 제거를 중복 계산하지 않아.\n채권 양도나 어음 할인은 위험·보상과 통제의 이전 여부에 따라 제거 또는 차입으로 처리할 수 있어. 이름이 “매각”이어도 자동 제거라고 단정하지 말고 문제의 요건을 따라.')],
['분류는 당기손익-공정가치야. 취득 수수료 2는 별도 비용으로 기록해.','기말 공정가치 115−최초 공정가치 100=평가이익 15야.','이 거래들만의 당기손익 순효과는 이익 15−수수료비용 2=13이야.'],
'단기매매 주식을 100에 사고 직접 수수료 2를 냈어. 기말 공정가치는 115이고 배당·처분은 없어. 기말 자산과 당기손익 순효과는?',
'금융자산 115 / 당기손익 순증가 13.',
'단기매매·만기보유·매도가능이라는 옛 분류 명칭을 현행 K-IFRS 분류와 무조건 일대일 대응시키지 않아.',[
('SPPI 충족 채무상품을 계약현금흐름 수취만 목적으로 관리한다. 별도 지정이 없다면 기본 측정은?','상각후원가',['항상 당기손익-공정가치','원가에서 영구 동결','항상 재고자산'],'사업모형과 현금흐름 조건을 함께 충족해 상각후원가로 분류해.'),
('단기매매 주식 가격 200, 거래수수료 5. 최초 주식 장부금액은?','200',['205','195','5'],'FVTPL 금융자산의 직접 거래원가 5는 비용이야.'),
('적격 지분상품에 FVOCI 선택을 했다. 처분 시 누적 OCI는?','당기손익으로 재분류하지 않는다',['반드시 매출로 재분류','반드시 이자수익으로 재분류','항상 현금으로 대체'],'FVOCI 지분상품과 FVOCI 채무상품의 재분류 규칙이 달라.'),
('필요한 손실충당금 40, 조정 전 충당금 대변잔액 15. 다른 변동이 없을 때 추가 비용은?','25',['40','55','15'],'필요 기말잔액 40−기존 대변잔액 15=25를 추가 설정해.')])

add('사채와 현재가치·유효이자율법',[
('표시이자율','사채 액면금액에 적용해 계약상 현금이자를 구하는 이자율.'),('유효이자율','예상 현금흐름을 최초 장부금액과 일치시키는 할인율.'),('할인발행','발행금액이 만기에 상환할 액면금액보다 작은 발행.'),('할증발행','발행금액이 만기에 상환할 액면금액보다 큰 발행.')],[
('오늘의 돈과 미래의 돈','오늘 100을 연 10%로 운용하면 1년 후 110이 돼. 반대로 1년 후 받을 110의 현재가치는 110÷1.1=100이야. 여러 기간이면 (1+r)의 기간 제곱으로 나눠.\n미래에 지급할 원금과 매년 지급할 이자는 시점이 다르기 때문에 각각 할인한 뒤 더해. 시험에서 현가계수나 연금현가계수를 주면 해당 기간과 이자율에 맞는 계수를 골라.'),
('발행가격은 원금과 이자의 현재가치 합계','매년 말 이자를 주고 만기에 원금을 갚는 사채의 발행가격은 현금이자×연금현가계수 + 액면원금×단일금액현가계수로 구할 수 있어. 여기서 할인에 사용하는 것은 시장이자율 등 유효이자율이야.\n표시이자율이 시장이자율보다 낮으면 투자자는 가격을 낮춰야 원하는 수익률을 얻으므로 할인발행이 돼. 표시이자율이 더 높으면 할증발행, 같으면 다른 요인이 없을 때 액면발행이야.'),
('현금이자와 이자비용','현금이자는 액면금액×표시이자율, 유효이자율법의 이자비용은 기초 사채 장부금액×유효이자율이야. 두 계산의 기준금액과 이자율을 섞지 마.\n할인발행이면 이자비용에서 현금이자를 뺀 차이가 장부금액을 늘려. 할증발행이면 현금이자가 이자비용보다 커서 그 차이만큼 장부금액이 줄어. 결국 만기 액면금액으로 수렴해.'),
('상각표는 세 줄로 시작해','기초 장부금액을 적고, 그 금액에 유효이자율을 곱해 비용을 구한 다음, 현금이자를 빼거나 더해 기말 장부금액을 계산해. 할인사채는 기말=기초+비용−현금이자야.\n현금이자를 지급했다고 비용과 장부금액 변화까지 한꺼번에 없어지는 게 아니야. 문제에 소수점 처리 조건이 있으면 매년 반올림 시점을 일관되게 적용해.'),
('발행원가와 중도상환','상각후원가 금융부채의 직접 발행원가는 원칙적으로 최초 장부금액에서 차감되어 유효이자율에 반영돼. 사채 액면금액 자체를 바꾸는 것은 아니야.\n중도상환 시 먼저 상환일까지의 이자를 반영한 장부금액을 구해. 그 장부금액보다 많이 지급하면 상환손실, 적게 지급하면 상환이익이야. 미지급 경과이자가 별도로 포함됐는지 확인해 원금 상환과 구분해.'),
('간단한 분개로 연결해','현금 950에 액면 1,000 사채를 할인발행했다면 순장부금액 950이라는 경제적 내용을 표시해. 교재에 따라 사채할인발행차금을 별도 차감계정으로 보여주기도 해.\n이자비용 76, 현금이자 50이라면 차변 이자비용 76 / 대변 현금 50, 할인차금 상각 26처럼 기록해 순부채가 26 증가하도록 연결해. 문제의 계정 표시방식을 따라가면 돼.')],
['첫해 현금이자는 액면 1,000×5%=50이야.','첫해 이자비용은 기초 장부금액 950×8%=76이야.','상각액 76−50=26, 기말 장부금액 950+26=976이야. 다음 해는 976에 유효이자율을 적용해.'],
'액면 1,000, 표시이자율 5%, 최초 장부금액 950, 유효이자율 8%가 주어졌어. 1년 후 첫 이자를 지급한 직후의 장부금액은? (발행가와 유효이자율은 문제의 주어진 값 사용)',
'976. 이자비용 76과 현금이자 50을 구분해.',
'상환손익은 상환일 장부금액과 상환대가로 계산해. 발행가나 액면만 비교하지 않아.',[
('액면 1,000, 표시 6%, 기초 장부금액 920, 유효 10%. 1년 이자비용은?','92',['60','100','55.2'],'이자비용은 920×10%=92, 현금이자는 1,000×6%=60이야.'),
('앞 조건의 기말 장부금액은?','952',['920','980','888'],'920+92−60=952이야.'),
('상환일 장부금액 980인 사채를 경과이자 없이 1,010에 상환했다. 결과는?','상환손실 30',['상환이익 30','상환손실 10','손익 없음'],'부채 980을 제거하려고 1,010을 줬으니 30 손실이야.'),
('1년 후 121을 지급하며 할인율 10%라면 현재가치는?','110',['121','133.1','100'],'121÷1.1=110. 2년 뒤가 아니라 1년 뒤라는 조건을 읽어.')])

add('자본거래·배당·기본주당이익',[
('자본금','발행주식의 액면금액 등에 따라 표시하는 법정자본 항목.'),('주식발행초과금','주식 발행대가가 액면금액을 초과한 부분 등의 자본잉여금.'),('이익잉여금','회사가 벌어들인 이익 중 배당 등으로 처분되지 않고 누적된 금액.'),('가중평균유통보통주식수','기간 중 유통된 보통주식수를 각 유통기간으로 가중평균한 수.')],[
('발행대금을 자본금과 나눠','액면 1,000원 주식 100주를 1,500원에 발행했다면 받은 돈은 150,000원이고 자본금은 100,000원, 주식발행초과금은 50,000원이야. 발행대금을 전부 수익으로 적지 않아.\n주식 발행에 직접 관련된 적격 거래원가는 세효과 등을 고려해 자본에서 차감하는 것이 원칙이야. 할인발행이나 발행원가 문제에서는 문제에 제시된 자본 항목과 처리 조건을 확인해.'),
('증자와 감자','유상증자는 대가를 받고 새 주식을 발행해 보통 자산과 자본을 늘려. 무상증자는 준비금 등을 자본금으로 옮겨 발행하는 방식으로 총자본이 반드시 늘지는 않아.\n감자는 자본금을 줄이는 일이야. 주주에게 자원을 반환하는 유상감자와 결손 보전 등을 위한 무상감자는 총자본에 미치는 영향이 다를 수 있어. 자본 항목 사이 이동과 총액 변동을 따로 봐.'),
('자기주식은 자산이 아니야','회사가 자기 회사 주식을 다시 사면 자본에서 차감해. 다른 회사 주식을 사서 금융자산을 보유하는 것과 달라. 처분이나 소각에서 생기는 차이도 당기손익으로 인식하지 않아.\n자기주식은 유통주식수에서도 빠지므로 주당이익 분모에 영향을 줘. 발행주식수와 유통주식수를 같다고 가정하기 전에 자기주식이 있는지 확인해.'),
('배당은 이익의 분배','현금배당 의무가 적절하게 확정되면 이익잉여금 감소와 지급할 배당금 의무를 기록하고, 실제 지급 때 현금을 줄여. 배당을 급여나 임차료처럼 비용으로 빼지 않아.\n보고기간 후 승인된 배당이 보고일 현재 의무가 아니면 그 보고일 부채로 인식하지 않아. 주식배당은 자본 내부의 이동과 주식수 변화를 함께 살펴봐.'),
('기본주당이익의 분자와 분모','기본주당이익은 보통주 귀속 손익을 가중평균유통보통주식수로 나눠. 단순 문제의 분자는 순이익에서 해당 우선주 배당 등을 조정한 금액이야.\n누적적 우선주의 당기 배당은 선언 여부와 무관하게 해당 금액을 조정하는 등 우선주 조건을 읽어야 해. 분모는 기말 주식수만 쓰지 않고 각 주식이 유통된 기간을 가중해.'),
('유통기간과 소급조정을 구분해','연초 1,000주에 7월 1일 현금 유상증자 600주라면 1,000×12/12+600×6/12=1,300주야. 자기주식을 사면 매입 이후 기간분을 분모에서 빼.\n주식분할·무상증자 등 대응 자원 증가 없이 주식수만 늘어나는 사건은 비교기간을 포함한 소급조정이 필요할 수 있어. 이를 현금 유상증자와 같은 방식으로만 월할하면 틀릴 수 있어. 희석주당이익은 잠재적 보통주와 반희석 여부를 검토하는 별도 확장 개념이야.')],
['보통주 귀속 이익은 순이익 2,800−해당 우선주배당 200=2,600이야.','가중평균주식수는 연초 1,000+7월 발행 600×6/12=1,300주야.','기본주당이익=2,600÷1,300=2야. 이익과 주식수의 단위를 일치시켜.'],
'순이익 2,800원, 차감할 우선주배당 200원, 연초 보통주 1,000주, 7월 1일 현금 유상증자 600주야. 자기주식이 없을 때 기본주당이익은?',
'1주당 2원.',
'회계상 이익과 자본거래를 구분해. 자기주식처분 차익은 당기 매출이나 투자수익이 아니야.',[
('액면 500원 200주를 주당 800원에 발행. 발행원가가 없을 때 주식발행초과금은?','60,000원',['100,000원','160,000원','300원'],'(800−500)×200=60,000원이야.'),
('자기주식을 취득하면 기본적으로 어떤 항목이 줄어?','자본',['매출','부채','영업비용'],'자기주식은 자본 차감항목으로 표시해.'),
('연초 1,200주, 10월 1일 현금 유상증자 400주. 다른 변동 없을 때 가중평균주식수는?','1,300주',['1,600주','1,200주','1,500주'],'1,200+400×3/12=1,300주야.'),
('기초 이익잉여금 500, 순이익 80, 배당 30. 다른 변동 없을 때 기말 이익잉여금은?','550',['610','580','450'],'500+80−30=550. 배당은 이익잉여금을 줄여.')])

add('현금흐름표·재무비율·마무리 분석',[
('영업활동','주된 수익 창출 활동과 투자·재무활동이 아닌 기타 활동.'),('투자활동','장기자산과 현금성자산에 포함되지 않는 투자의 취득·처분 활동.'),('재무활동','납입자본과 차입금의 크기·구성에 변화를 일으키는 활동.'),('간접법','손익에서 비현금항목과 운전자본 변동 등을 조정하여 영업현금흐름을 구하는 방법.')],[
('세 종류의 현금 흐름','상품 판매대금 회수와 상품대금 지급은 일반적으로 영업활동, 기계 구입과 처분은 투자활동, 주식 발행과 차입·원금 상환은 재무활동으로 생각해.\n기계를 외상으로 샀다면 자산과 부채가 늘어도 그 시점에 현금흐름은 없어. 중요한 비현금 투자·재무거래는 현금흐름표 본문의 유출입에 억지로 넣지 않고 별도 공시를 검토해.'),
('직접법은 받은 돈과 낸 돈을 모아','매출액에서 매출채권 증가를 빼면 단순 조건의 매출대금 현금수입이 돼. 매출은 있었지만 아직 못 받은 부분을 빼는 거야. 매출채권이 감소하면 과거 외상대금까지 회수했으므로 더해.\n매입대금 현금지급은 매입액에 매입채무 감소를 더하거나 증가를 빼서 계산해. 매입액 자체는 단순 사례에서 매출원가+기말재고−기초재고로 구해. 평가손실 등 별도 변동이 없다는 조건이 필요해.'),
('간접법은 이익을 현금으로 바꿔','감가상각은 비용으로 순이익을 줄였지만 그 기간에 동일한 현금이 직접 나간 것은 아니므로 가산해. 기계처분이익은 손익에 들어 있지만 해당 현금은 투자활동이므로 영업현금 계산에서 차감해.\n영업 관련 매출채권·재고 증가 등은 일반적으로 차감하고, 매입채무 등 영업부채 증가는 가산해. 거래별 비현금 변동이나 투자·재무 항목이 섞였다면 단순 잔액차이를 그대로 쓰지 않아.'),
('이자·배당·법인세 분류 조건','이자·배당 현금흐름은 적용 기준과 기업 성격, 일관된 정책을 확인해. 2026년 기준의 IAS 7 체계에서는 비금융기업의 이자지급에 영업 또는 재무활동 등 허용되는 선택이 있어.\n법인세 현금흐름은 일반적으로 영업활동이지만 특정 투자·재무거래와 구체적으로 관련되면 해당 활동으로 분류할 수 있어. 2027년 이후 새 표시기준 적용 여부 등은 시험의 적용 기준을 우선 확인해. 이 단원 예제는 분류가 명시된 거래만 사용해.'),
('유동성·안정성 비율','유동비율은 유동자산÷유동부채×100, 당좌비율은 당좌자산÷유동부채×100이야. 당좌자산을 단순히 유동자산−재고로 주는 문제도 있지만 선급비용 등 제외 항목이 있는지 확인해.\n부채비율은 부채÷자본×100이야. 자산으로 나누는 부채구성비율과 구분해. 분모가 0이거나 자본이 음수이면 단순한 “높을수록 나쁘다” 해석을 그대로 하기 어렵다는 점도 기억해.'),
('수익성·활동성 비율','매출총이익률=(매출액−매출원가)÷매출액×100, 순이익률=순이익÷매출액×100이야. 원가에 대한 이익 비율과 매출에 대한 이익률은 분모가 달라.\n매출채권회전율은 문제 조건에 따라 순외상매출액÷평균매출채권, 재고회전율은 매출원가÷평균재고를 써. 평균 잔액은 단순 문제에서 (기초+기말)÷2야. 높은 비율 하나로 기업의 모든 상태를 단정하지 않아.')],
['순이익 100에 비현금 감가상각 20을 더하고 투자활동 처분이익 5를 빼 115야.','매출채권 증가 15와 재고 증가 10을 빼면 90이야.','매입채무 증가 8을 더해 영업현금흐름 98이야. 다른 조정은 없다는 조건을 확인해.'],
'순이익 100, 감가상각 20, 기계처분이익 5, 영업 매출채권 증가 15, 재고 증가 10, 매입채무 증가 8. 다른 조정이 없을 때 간접법 영업현금흐름은?',
'98. 순이익 100과 현금흐름 98은 서로 다른 수치야.',
'기계 판매대금은 투자현금흐름, 처분손익은 순이익에 들어간 차액이야. 둘을 같은 금액으로 보지 않아.',[
('순이익 50, 감가상각 10, 영업 매출채권 증가 8. 다른 조정 없을 때 영업현금흐름은?','52',['68','32','50'],'순이익 50에 현금 지출이 없는 감가상각 10을 다시 더해. 매출채권 증가 8은 수익에 포함됐지만 아직 못 받은 현금이므로 빼면 52야.'),
('유동자산 600, 유동부채 300. 유동비율은?','200%',['50%','300%','100%'],'600÷300×100=200%야.'),
('기초재고 80, 기말재고 120, 매출원가 500. 재고회전율은?','5회',['4.17회','6.25회','2.5회'],'평균재고 (80+120)÷2=100. 500÷100=5회야.'),
('회사가 은행 대출 원금을 현금으로 갚았다. 일반적인 활동 분류는?','재무활동',['영업활동','투자활동','비현금거래'],'차입금 원금의 상환은 재무활동 현금유출이야.')])

add('결산·회계변경·오류수정·내부통제',[
('회계정책','재무제표 작성·표시에 사용하는 구체적인 원칙·기준·관행 등.'),('회계추정치 변경','새로운 정보·상황 변화 등에 따라 측정상의 추정을 수정하는 것.'),('전기오류','과거 재무제표 작성 때 이용가능한 신뢰성 있는 정보를 누락·오용하여 생긴 오류.'),('내부통제','신뢰성 있는 보고와 업무 수행 등을 위해 마련한 정책·절차의 체계.')],[
('결산 조정은 다섯 요소를 정리해','미수수익·미지급비용처럼 발생했지만 아직 기록되지 않은 항목을 반영해. 선급비용·선수수익은 이미 기록한 금액을 실제 사용·수행한 기간에 맞춰 나눠.\n감가상각, 손상, 재고실사, 충당부채 등도 결산에서 검토해. 현금을 주고받지 않는 수정분개가 많으므로 “현금이 안 움직였으니 아무것도 안 한다”는 생각을 버리면 이해하기 쉬워.'),
('수정 전후 시산표와 마감','수정 전 시산표에 결산수정분개를 반영한 뒤 수정 후 잔액으로 재무제표를 작성해. 손익계정은 마감해 기간 성과를 자본에 연결하고 자산·부채·자본 잔액은 다음 기간으로 이어져.\n시산표가 일치해도 계정 오기나 거래 누락이 있을 수 있으므로 증빙·원장과 대조해야 해. 장부 숫자가 맞는 것과 경제적 내용이 맞는 것은 함께 확인할 일이지 하나로 대체되지 않아.'),
('정책 변경과 추정 변경','회계정책 변경은 원칙적으로 소급 적용해 비교정보와 관련 기초자본 등을 조정해. 다만 새 기준의 경과규정이나 소급이 실무적으로 불가능한 경우 등 예외가 있어.\n내용연수·잔존가치처럼 새로운 정보에 따라 추정이 달라졌다면 변경한 기간과 미래기간에 전진적으로 반영해. 과거에 잘못 계산한 것을 나중에 발견한 오류와는 원인이 달라.'),
('추정 변경 뒤 감가상각','기계의 변경 시점 장부금액에서 새 잔존가치를 뺀 금액을 남은 내용연수로 배분해. 정액법 사례에서는 과거 원가를 처음부터 다시 계산해서 이전 상각을 전부 지우지 않아.\n과거에 이용할 수 있었던 정보를 잘못 적용했다면 추정 변경이 아니라 오류일 수 있어. “새 정보가 생겼나, 원래 알 수 있었던 것을 잘못 기록했나”로 나눠봐.'),
('중요한 전기오류와 보고기간 후 사건','중요한 전기오류는 원칙적으로 비교정보 등을 소급 재작성해 수정해. 무조건 발견한 해의 당기비용으로 몰아서 처리하면 비교가능성이 훼손될 수 있어.\n보고기간 후 사건은 보고일에 존재하던 상황에 대한 증거인지, 보고일 뒤에 새로 생긴 상황인지 구분해. 전자는 수정사건, 후자는 일반적으로 비수정사건이지만 중요하면 공시를 검토해.'),
('회계정보시스템과 통제','증빙 확인 → 승인 → 입력 → 검증 → 보고라는 흐름에서 누가 무엇을 했는지 추적할 수 있어야 해. 현금 보관·거래 승인·장부 기록을 한 사람에게 모두 맡기지 않는 업무분장은 오류와 부정을 줄이는 통제야.\n접근권한, 변경기록, 정기 백업, 은행잔액 대사, 실사, 전표 일련번호 점검 등을 연결해. 프로그램이 자동 합계를 맞춰줘도 잘못된 계정·중복 입력·누락을 모두 막아주는 것은 아니야.'),
('은행계정조정표','회사 장부와 은행 잔액은 미인출수표·미기입예금 같은 시점차이, 은행 수수료·추심 같은 미기록 거래, 오류로 다를 수 있어. 은행측 조정과 회사 장부측 조정을 나눠 양쪽의 실제 잔액을 맞춰.\n미인출수표는 은행 잔액에서 빼고, 회사가 아직 기록하지 않은 은행수수료는 회사 장부에서 빼는 식이야. 회사가 이미 정확히 기록한 시점차이는 회사 장부에 중복 분개하지 않아.')],
['변경 시점 장부금액 600에서 새 잔존가치 60을 빼 540이야.','새로 예상한 잔여 사용기간 3년으로 나누면 180이야.','새 정보에 따른 추정 변경이므로 앞으로 연 180씩 배분하고 과거 상각액은 소급 수정하지 않아.'],
'새 정보에 따라 기계의 잔여 내용연수를 3년, 잔존가치를 60으로 변경했어. 변경일 장부금액 600, 정액법이고 오류가 아니라면 이후 1년 상각액은?',
'180.',
'정책·추정·오류의 이름만 외우지 말고 변경 원인과 적용 시점을 같이 설명해봐.',[
('새 정보에 따라 내용연수를 변경했다. 기본 처리는?','변경 기간과 미래기간에 반영',['항상 과거 전액 취소','항상 자본금 변경','아무 영향 없음'],'회계추정치 변경은 전진적으로 반영해.'),
('은행 잔액 500, 미인출수표 50, 미기입예금 20. 은행측 조정잔액은?','470',['530','570','430'],'500−50+20=470이야.'),
('장부에 아직 기록하지 않은 은행 수수료 5를 확인했다. 회사 장부의 예금은?','5 감소',['5 증가','변동 없음','10 감소'],'수수료 비용을 반영하고 보통예금을 5 줄여.'),
('현금보관·지급승인·장부기록을 서로 다른 담당자가 맡기는 통제는?','업무분장',['선입선출','감가상각','공정가치평가'],'한 사람이 거래의 전 과정을 독점하지 않게 해 오류·부정 위험을 줄이는 통제야.')])

add('법인세비용과 세전·세후이익',[
('세전이익','법인세비용을 차감하기 전 회계상 이익.'),('과세소득','세법에 따라 법인세를 계산하기 위해 산출한 소득.'),('당기법인세','당기 등의 과세소득에 대해 납부하거나 환급받을 법인세 금액.'),('일시적차이','자산·부채의 회계상 장부금액과 세무기준액 사이에서 향후 해소되는 차이.')],[
('회계이익과 세금 계산용 이익','회계기준은 성과를 보고하기 위한 것이고 세법은 과세할 소득과 세액을 정해. 그래서 회계상 비용으로 기록했어도 세법에서 공제하지 않는 항목 등이 생겨 세전이익과 과세소득이 다를 수 있어.\n법인세비용을 계산할 때 모든 회계이익에 임의로 한 세율을 곱하면 안 돼. 시험에서 과세소득·세율·이연법인세 조건을 어떻게 줬는지 읽어. 아래 세율 20%는 계산 연습용 가정이야.'),
('당기법인세부터 계산해','단일 세율이라는 가정 아래 과세소득 500, 세율 20%면 당기법인세는 100이야. 중간예납 등으로 이미 30을 납부했다면 미지급세액은 다른 조건이 없을 때 70이야.\n당기법인세 총액과 아직 납부하지 않은 부채 금액은 달라. 이미 납부한 금액은 비용을 없애는 것이 아니라 지급액·자산과 상계하여 남은 의무를 정리하는 것이야.'),
('일시적차이와 영구적차이','감가상각 시기 차이처럼 지금 회계와 세법에서 달라도 나중에 해소되는 차이는 일시적차이를 생각할 수 있어. 반면 세법상 영구적으로 인정하지 않는 항목은 나중에 반대로 해소되지 않아.\n일시적차이는 향후 세금이 증가하거나 감소하는 효과를 만들 수 있어. 가산할 일시적차이는 이연법인세부채, 차감할 일시적차이는 인식 요건을 충족하는 범위에서 이연법인세자산을 검토해.'),
('이연법인세를 한 번 연결해','기계 장부금액이 600, 세무기준액이 500이면 회계상 회수할 금액에 비해 앞으로 세무상 공제할 금액이 적을 수 있어. 단순 사례에서 가산할 일시적차이 100에 적용세율을 곱해 이연법인세부채를 구해.\n차감할 일시적차이가 있다고 이연법인세자산을 무조건 인식하지는 않아. 활용할 과세소득의 발생 가능성 등 인식 요건을 확인해. 이연법인세는 할인하지 않아.'),
('비용과 납부액을 구분해','관련 항목이 모두 당기손익에 인식되고 다른 변동이 없다면 법인세비용은 당기법인세+이연법인세부채 증가−이연법인세자산 증가로 연결할 수 있어. 자본·기타포괄손익 항목의 세효과 등은 해당 위치를 별도로 판단해.\n법인세 납부액만 보고 법인세비용을 결정하지 않아. 기초·기말 미지급세금, 선납세금, 이연세금이 다르게 움직일 수 있기 때문이야.'),
('손익계산서 마지막 줄까지','매출액에서 매출원가를 빼면 매출총이익, 여기에 판매관리비 등과 기타 수익·비용을 반영해 세전이익을 구하고 법인세비용을 차감해 당기순이익을 구하는 단순 구조를 익혀.\n실제 표시항목과 중단영업 등은 문제 조건을 따라야 해. 이 수업에서는 세법 신고서 작성보다 주어진 세금 자료가 회계상 비용과 부채, 순이익에 어떻게 연결되는지 이해하는 데 초점을 둬.')],
['과세소득 500×가정세율 20%=당기법인세 100이야.','당기손익 관련 이연법인세부채가 10 증가하고 다른 변동이 없으면 법인세비용은 110이야.','세전이익 550−법인세비용 110=당기순이익 440이야.'],
'세전이익 550, 과세소득 500, 가정세율 20%, 당기손익 관련 이연법인세부채 증가 10, 이연법인세자산 등 다른 변동 없음. 순이익은?',
'440. 당기법인세 100과 법인세비용 110을 구분해.',
'여기 제시한 세율은 학습용 가정이야. 실제 세율을 암기하는 문제로 이해하지 않아.',[
('과세소득 300, 가정세율 20%, 선납세금 15. 다른 조건 없을 때 미지급 당기법인세는?','45',['60','15','75'],'총세금 300×20%=60에서 선납 15를 빼 45야.'),
('세전이익 500, 법인세비용 100. 다른 조정 없을 때 순이익은?','400',['600','500','100'],'500−100=400이야.'),
('기계 장부금액 600, 세무기준액 500. 가산할 일시적차이에 적용할 가정세율 20%. 예외 없음. 이연법인세부채는?','20',['100','120','0'],'차이 100×20%=20이야.'),
('당기법인세 80, 당기손익 관련 이연법인세자산 5 증가, 그 밖의 변동 없음. 법인세비용은?','75',['85','80','5'],'앞으로의 세금 감소 효과인 이연법인세자산 증가 5를 차감해 75야.')])

# Fill small but explicit syllabus items in the chapters where learners encounter them.
def section(lid,title,text):d['lessons'][lid-1]['book']['sections'].append(dict(title=title,paragraphs=text.split('\n')))
section(21,'회계관련 규정은 무엇을 정할까?','재무보고에는 적용 회계기준이 있고, 세금 계산에는 세법이 있으며, 회사의 자본·기관 등에 관한 법규도 따로 있어. 모든 규정을 하나의 계산법으로 섞지 말고 문제에서 K-IFRS 등 어느 기준을 전제하는지 읽어.\n재무회계의 수익·비용과 세법의 익금·손금이 항상 같지는 않아. 회계기준에 따라 먼저 장부와 재무제표를 작성하고 세무상 조정이 필요한 항목을 별도로 판단한다고 이해하면 돼.')
section(25,'웹사이트 개발원가','웹사이트도 내부창출 무형자산의 요건을 충족하는지 판단해. 기획 단계 지출은 연구단계처럼 비용으로 보는 것이 기본이며, 개발 단계 지출은 기술적 실현가능성·미래 효익 등 개발비 인식 요건을 입증해야 해.\n회사의 제품·서비스를 광고·홍보하는 것이 주된 목적이라면 그 웹사이트 지출은 일반적으로 발생 시 비용이야. 운영·유지 지출도 자동 자산화하지 않아. 결제 기능 등으로 수익을 창출하는 사이트라도 지출 전부가 아닌 요건을 충족한 원가만 검토해.')
section(30,'개인기업의 자본과 인출금','개인기업에서는 소유주의 추가 출자는 자본 증가, 사업주가 개인 목적으로 사업 자금을 가져간 인출은 자본 감소야. 사업주가 개인 생활비로 썼다는 이유로 회사의 급여나 임차료 비용에 넣지 않아.\n다른 자본 변동이 없으면 기말자본=기초자본+추가출자+순이익−인출액이야. 주식회사의 자본금·배당과 계정 표시가 다를 수 있지만 소유주와의 거래를 손익에서 구분한다는 원리는 같아.')
section(32,'입금·출금·대체 전표와 장부','전표는 거래 내용을 일정한 형식으로 기록하고 승인·증빙과 연결하는 문서야. 현금이 들어오면 입금전표, 현금이 나가면 출금전표, 현금 수수가 없는 거래는 대체전표를 쓰는 체계를 생각해. 실제 프로그램의 전표 구분은 화면의 지시를 따라.\n현금 10을 빌리면 입금거래, 현금으로 월세 3을 내면 출금거래, 상품 5를 외상 매입하면 대체거래야. 복합거래는 분할·대체 처리 등 해당 전표체계의 규칙을 확인하고 동일 거래를 두 번 입력하지 않아.')
section(4,'현금·요구불예금·소액현금','통화와 통화대용증권 등 현금, 요구하면 인출할 수 있는 요구불예금, 요건을 충족한 단기 투자자산인 현금성자산을 구분해. 현금성자산은 통상 취득일로부터 만기가 3개월 이내인 투자 등을 생각하지만 단기 현금수요 목적과 가치변동위험 요건도 필요해.\n소액현금 정액자금전도제는 일정액을 맡기고 지출 증빙에 따라 부족액을 보충하는 방식이야. 장부상 현금과 실사 현금이 다르면 원인을 조사해 현금과부족 등을 정리하고, 원인 확인 후 적절한 계정으로 대체해.')
section(4,'어음과 거래처별 원장','받을어음은 정해진 기일에 금액을 받을 권리, 지급어음은 지급할 의무야. 액면 100, 연 이자율 6%, 3개월 이자부어음이면 단순 월할 이자 100×6%×3/12=1.5, 만기 수취액 101.5야.\n매출처원장은 고객별 받을 돈, 매입처원장은 공급자별 지급할 돈을 보조적으로 관리해. 개별 고객 잔액의 합계가 총계정원장의 관련 통제계정 잔액과 맞는지 대조하면 누락·중복을 찾는 데 도움이 돼.')
section(4,'어음 할인과 담보 제공','만기수취액 100인 어음을 만기 3개월 전에 연 8%로 할인하고 단순 월할 계산하라는 조건이면 할인료 100×8%×3/12=2, 수취현금 98이야. 이 계산과 금융자산을 장부에서 제거할 수 있는지는 별개의 판단이야.\n위험·보상과 통제 이전 요건을 충족해 제거하는지, 실질적으로 담보 차입인지 문제 조건을 읽어. 담보로 제공한 것만으로 채권이 없어지지 않아. 담보 차입이라면 채권을 유지하고 차입부채를 인식할 수 있어.')
section(26,'기타채권·채무의 이름 정리','돈을 빌려준 권리는 대여금, 빌린 의무는 차입금이야. 상품의 통상 매매 외 거래에서 아직 받지 못한 금액은 미수금, 아직 지급하지 않은 금액은 미지급금을 생각해. 상품 주문 시 미리 지급한 선급금과 받은 선수금도 구분해.\n지급은 했는데 내용·계정이 확정되지 않으면 가지급금, 입금 내용이 확정되지 않으면 가수금 같은 임시계정을 쓸 수 있어. 결산까지 무작정 남겨두지 말고 원인을 확인해 적절한 계정으로 대체해. 예수금은 원천징수액처럼 일시 보관하고 타인에게 지급할 의무야.')
section(23,'가격 상승 시 원가공식의 효과','다른 조건이 같고 매입단가가 계속 오르는 상황에서 선입선출법은 과거의 낮은 단가를 먼저 판매원가에 배분해. 그래서 평균법보다 매출원가가 낮고 기말재고와 매출총이익이 높게 나타날 수 있어.\n이는 원가배분 가정의 효과이고 실제 현금이 더 생겼다는 뜻은 아니야. 매입단가 하락이면 방향이 반대로 바뀔 수 있으므로 “선입선출이면 무조건 이익이 크다”고 외우지 않아.')
section(31,'네 가지 보고서를 같은 숫자로 작성해','회사를 현금 출자 300으로 시작하고 100을 빌린 뒤, 당기 서비스 수익 80을 전액 현금으로 받고 당기 비용 30을 지급했다고 하자. 배당·세금·기타포괄손익 등 다른 거래는 없다는 학습용 조건이야. 기말현금은 300+100+80−30=450, 부채 100, 자본 350으로 재무상태표가 맞아.\n포괄손익계산서는 수익 80−비용 30=순이익 50, 기타포괄손익이 없으므로 총포괄이익도 50이야. 자본변동표는 기초 0+출자 300+이익 50=350, 현금흐름표는 영업 +50, 투자 0, 재무 +400으로 현금증가 450이야. 한 거래를 네 보고서에서 서로 다른 질문으로 보여주는 거야.')

# Cost chapters retain their original IDs and questions; add full computations.
def cost(lid,sections,problem,steps,answer,qa):
 b=d['lessons'][lid-1]['book']
 for t,p in sections:section(lid,t,p)
 b['extraWorked']=[dict(prompt=problem,steps=steps,answer=answer)]
 for n,(q,a,wrong,e) in enumerate(qa):d['questions'].append(dict(id=f'{lid:02}-X{n+1}',lesson=lid,subject=C,level='응용',kind='자체 제작',prompt=q,choices=[a]+wrong,correct=0,explanation=e))

cost(11,[('원가회계와 관리회계의 관계','원가회계는 제품·서비스 등의 원가를 측정·집계·배분하는 데 초점을 두고, 재고평가와 손익계산뿐 아니라 내부 관리에도 정보를 제공해. 관리회계는 경영자의 계획·통제·의사결정을 돕는 더 넓은 활동이야.\n재무회계에 쓸 제품원가와 주문 수락 결정에 쓸 관련원가는 목적이 다르므로 같지 않을 수 있어. 원가대상을 무엇으로 정했는지부터 읽어야 해.'),('직접과 간접은 원가대상에 따라','가구 한 개에 들어간 목재는 그 제품에 직접 추적할 수 있으면 직접재료야. 여러 제품에 공동으로 쓰는 공장 전기료는 제품별로 직접 추적하기 어려워 간접원가로 배부해.\n한 공장만을 대상으로 하면 그 공장의 임차료는 공장에 직접 추적될 수 있지만 개별 제품에는 간접원가일 수 있어. 직접·간접은 고정·변동과 다른 분류축이라 고정 직접원가도 가능해.'),('기회원가·매몰원가·관련원가','기회원가는 어떤 선택 때문에 포기한 차선 대안의 효익이야. 보통 장부에 기록하지 않아도 의사결정에서는 중요할 수 있어. 매몰원가는 이미 발생해 현재 선택으로 바꿀 수 없는 원가야.\n관련원가는 미래에 발생하고 대안 사이에서 차이가 나는 원가야. 과거에 비싸게 샀다는 이유만으로 그 취득원가를 모든 새 의사결정에 다시 포함하지 않아.')],
'직접재료 40, 직접노무 30, 공장감가상각 20, 공장전기료 10, 본사 광고비 15가 발생했어. 제조원가·기본원가·가공원가는?',
['제조간접원가는 공장감가상각 20+공장전기료 10=30이야.','제조원가 40+30+30=100, 기본원가는 직접재료 40+직접노무 30=70이야.','가공원가는 직접노무 30+제조간접원가 30=60이야. 본사 광고비 15는 이 제조원가에 넣지 않아.'],'제조원가 100 / 기본원가 70 / 가공원가 60.',[
('직접재료 30, 직접노무 20, 제조간접 10. 가공원가는?','30',['50','60','10'],'직접노무 20+제조간접 10=30이야.'),('본사 영업부 광고비는 일반적으로?','기간원가',['직접재료원가','재공품','제품제조원가'],'판매·관리 활동의 비용은 일반적으로 발생 기간 비용이야.'),('이미 구입한 기계의 회수불가능한 과거 취득원가는 새 대안 결정에서?','매몰원가',['항상 관련원가','기회원가','매출채권'],'현재 선택으로 바뀌지 않는 과거 원가야.'),('포기한 차선 대안의 이익은?','기회원가',['직접노무원가','감가상각누계액','매입채무'],'기회비용은 선택 때문에 포기하는 효익이야.')])

cost(12,[('관련범위 안에서만 선형 관계','고정원가 총액이 일정하고 단위당 변동원가가 일정하다는 가정은 정해진 조업범위에서 사용해. 생산량이 너무 늘어 새 공장을 빌리면 고정원가도 계단식으로 변할 수 있어.\n총고정원가와 단위당 고정원가를 혼동하지 마. 고정원가 100을 10개에 나누면 개당 10, 20개에 나누면 개당 5야.'),('고저점법으로 혼합원가를 나눠','조업도가 가장 높은 관측치와 가장 낮은 관측치를 골라 원가 차이를 조업도 차이로 나누면 단위당 변동원가 추정치가 나와. 원가가 가장 높거나 낮은 점을 임의로 고르는 것이 아니야.\n그 뒤 고점 또는 저점의 총원가에서 변동원가분을 빼면 고정원가 추정치가 돼. 두 점만 쓰기 때문에 비정상 관측치가 있으면 결과가 왜곡될 수 있어.'),('원가함수로 다른 조업도를 예상해','총원가 Y=고정원가 a+단위당 변동원가 b×조업도 X로 써. 식을 만든 자료의 관련범위를 벗어난 예측인지 점검해야 해.\n산포도는 자료의 패턴을 보고, 회귀분석은 여러 관측치를 이용해 관계를 추정해. 추정식은 실제원가가 언제나 정확히 같다는 보장이 아니라 의사결정에 쓰는 모형이야.')],
'조업도 100시간일 때 원가 700, 300시간일 때 원가 1,300이야. 고저점법 추정식과 200시간의 원가는?',
['단위변동원가=(1,300−700)÷(300−100)=3이야.','고정원가=700−3×100=400이야.','원가식 Y=400+3X이므로 200시간은 400+600=1,000이야.'],'Y=400+3X / 200시간 예상원가 1,000.',[
('고점 500개·원가 2,000, 저점 100개·원가 800. 단위변동원가는?','3',['4','8','1,200'],'(2,000−800)÷(500−100)=3이야.'),('앞 조건에서 고정원가는?','500',['800','1,500','300'],'800−3×100=500이야.'),('총고정원가 600, 생산 200개. 단위당 고정원가는?','3',['600','200','120,000'],'전체 고정원가 600을 생산량 200개에 나누어 배분하면 한 개당 3이야. 생산량이 늘어도 총고정원가가 같다는 것과 단위당 고정원가가 같다는 것은 달라.'),('고저점법에서 고점·저점을 고르는 기준은?','조업도',['총원가만','단위원가만','날짜의 앞뒤'],'조업도가 가장 높은 점과 낮은 점을 골라.')])

cost(13,[('네 계정의 경계를 따라가','재료를 사면 원재료, 생산에 쓰면 재공품, 완성하면 제품, 판매하면 매출원가로 원가가 이동해. 직접노무와 배부된 제조간접원가도 생산 중인 재공품에 모여.\n아직 안 팔았다고 모든 원가가 재공품인 것은 아니야. 완성은 됐지만 팔리지 않은 것은 제품에 남아. 완성 여부와 판매 여부를 각각 확인해.'),('제조원가명세서의 골격','직접재료 사용액+직접노무원가+제조간접원가=당기총제조원가야. 여기에 기초재공품을 더하고 기말재공품을 빼면 당기제품제조원가가 돼.\n당기제품제조원가는 이번에 완성해 제품계정으로 넘어간 원가야. 그 금액에 기초제품을 더하고 기말제품을 빼면 단순 조건의 매출원가가 돼.'),('제조간접원가 배부차이는 마지막에 확인해','예정배부액을 쓴 제조원가라면 실제발생액과의 차이가 남아 있을 수 있어. 문제에서 매출원가에 전액 조정하라는지, 재공품·제품·매출원가에 배분하라는지 읽어.\n조정 전 매출원가와 조정 후 매출원가를 묻는 문제는 답이 다를 수 있어. 모든 계산의 시작에 실제원가인지 예정배부액인지 표시해두면 좋아.')],
'기초재공품 20, 직접재료 80, 직접노무 50, 제조간접 30, 기말재공품 25, 기초제품 40, 기말제품 35야. 다른 조정이 없을 때 제품제조원가와 매출원가는?',
['당기총제조원가=80+50+30=160이야.','당기제품제조원가=기초재공품 20+160−기말재공품 25=155야.','매출원가=기초제품 40+155−기말제품 35=160이야.'],'제품제조원가 155 / 매출원가 160.',[
('기초재공품 10, 당기총제조원가 90, 기말재공품 20. 제품제조원가는?','80',['100','120','90'],'10+90−20=80이야.'),('기초제품 30, 당기완성원가 80, 기말제품 25. 매출원가는?','85',['75','135','55'],'30+80−25=85야.'),('생산을 마쳤지만 아직 팔지 않은 물건의 원가는 어디에 남아?','제품',['재공품','매출원가','광고비'],'생산 완료는 제품으로 이동, 판매 완료는 매출원가로 이동이야.'),('원재료를 직접 생산에 투입하면 기본적으로 증가하는 계정은?','재공품',['매출','자본금','제품매출원가'],'생산 중인 원가를 재공품에 모아.')])

cost(14,[('매입과 소비를 따로 계산해','매입원가에는 구매가격에서 할인 등을 빼고 필요한 운반·취급원가를 더해. 이번 달에 샀어도 아직 창고에 있으면 이번 달 소비원가가 아니야.\n재료소비액=기초재료+순매입−기말재료라는 흐름을 먼저 맞춰. 감모·반품·평가 변동이 주어졌다면 따로 반영해 단순식을 무조건 적용하지 않아.'),('소비수량과 단가를 결합해','재료출고 수량을 파악한 뒤 선입선출·평균 등 조건에 맞는 단가를 적용해. 재료소비 총액 중 간접재료가 있으면 제조간접원가로 구분하고 직접재료만 재공품에 직접 추적해.\n철제 가구의 철판과 공용 윤활유처럼 제품에 직접 추적할 수 있는 정도가 달라. 금액이 작다는 이유만으로 언제나 간접인 것은 아니고 원가대상과 경제적 추적가능성을 함께 봐.')],
'기초재료 50, 구매가격 200, 매입할인 10, 필요한 매입운반비 5, 기말재료 45야. 소비액 중 간접재료 20이면 직접재료원가는?',
['순매입원가=200−10+5=195야.','총재료소비액=50+195−45=200이야.','직접재료원가=총소비 200−간접재료 20=180이야.'],'직접재료원가 180 / 간접재료원가 20.',[
('기초 40, 매입 160, 기말 30. 다른 변동 없을 때 재료소비액은?','170',['190','150','160'],'40+160−30=170이야.'),('총재료소비 170 중 간접재료 25. 직접재료는?','145',['195','170','25'],'전체 재료소비액 170에는 직접재료와 간접재료가 모두 들어 있어. 간접재료 25를 빼면 특정 제품에 직접 추적하는 재료원가 145가 남아.'),('매입가격 100, 할인 5, 필요한 운반비 3. 취득원가는?','98',['108','102','95'],'100−5+3=98이야.'),('제품 전체에 공통 사용한 간접재료는 보통 어디에 집계해?','제조간접원가',['항상 직접노무','항상 자본금','매출액'],'제조간접원가에 모은 뒤 적절한 기준으로 제품에 배부해.')])

cost(15,[('노무원가는 근로 제공에 따라','당기에 지급한 금액에는 전기에 발생한 미지급급여가 섞일 수 있어. 당기 발생액을 구하려면 지급액에서 기초 미지급액을 빼고 기말 미지급액을 더해.\n급여 선급액까지 있다면 지급액+기말미지급−기초미지급+기초선급−기말선급의 관계를 적용할 수 있어. 단순히 현금 지급만 더하지 않아.'),('직접노무와 간접노무','제품에 직접 추적 가능한 작업 인건비는 직접노무, 공장감독·공통지원 인건비 등은 간접노무로 구분할 수 있어. 간접노무는 제조간접원가에 집계해.\n정상적인 유휴시간이나 특정 작업 때문에 발생한 초과근무수당 등은 원인과 정책에 따라 처리 대상이 달라질 수 있어. 문제에서 특정 작업에 직접 부과하라고 했는지 공통 간접원가인지 확인해.')],
'급여 지급액 120, 기초미지급 10, 기말미지급 15, 기초선급 4, 기말선급 9야. 당기 발생액 중 간접노무가 20이면 직접노무는?',
['기간 조정한 발생액=120−10+15+4−9=120이야.','발생액 120에서 간접노무 20을 따로 빼.','직접노무원가=100, 간접노무원가=20이야.'],'직접노무원가 100.',[
('급여 지급 100, 기초미지급 8, 기말미지급 12, 선급 없음. 발생액은?','104',['96','120','100'],'100−8+12=104야.'),('급여 지급 100, 미지급 없음, 기초선급 5, 기말선급 15. 발생액은?','90',['110','120','100'],'100+5−15=90이야.'),('제품에 직접 추적하지 못하는 공장 감독자의 임금은 일반적으로?','간접노무원가',['판매수익','직접재료','금융부채'],'공장 공통 인건비는 제조간접원가로 집계해.'),('발생 노무원가 150, 간접노무 35. 직접노무는?','115',['185','150','35'],'당기에 발생한 노무원가 150에서 제조간접원가로 처리하는 간접노무 35를 제외해. 남은 115가 제품에 직접 추적할 직접노무원가야.')])

cost(16,[('배부의 목적과 기준','공통 원가를 원가대상에 나누는 것은 재고평가, 가격·성과 판단 등에 필요한 제품원가를 만들기 위해서야. 인과관계나 수혜 정도를 잘 나타내는 배부기준을 선택해야 해.\n기계 중심 공정이면 기계시간, 노동 중심이면 직접노무시간 등으로 배부할 수 있어. 단순히 모든 제품에 똑같이 나누는 것이 항상 적절한 것은 아니야.'),('예정배부와 실제배부','예정배부율=예정 제조간접원가÷예정 배부기준량, 제품 배부액=예정배부율×해당 제품의 실제 기준량이야. 분모의 예정량과 배부할 때의 실제량을 구분해.\n실제배부율을 쓰는 문제라면 실제총원가÷실제총기준량을 사용해. 계절별 변동이나 계산 시점 때문에 실제배부와 예정배부 결과는 다를 수 있어.'),('배부차이를 조정해','실제발생액이 예정배부액보다 크면 과소배부, 작으면 과대배부야. 전액 매출원가 조정 조건이면 과소는 매출원가에 더하고 과대는 빼.\n차이가 중요해서 재공품·제품·매출원가에 배분하라는 조건이면 그 기준에 따라 나눠. “과소=무조건 당기 비용 전액”이라고 단정하지 않아.')],
'예정간접원가 1,200, 예정기계시간 600시간, 실제기계시간 550시간, 실제발생원가 1,250이야. 예정배부액과 과소·과대배부는?',
['예정배부율=1,200÷600=시간당 2야.','예정배부액=2×실제시간 550=1,100이야.','실제 1,250−배부 1,100=150 과소배부. 매출원가 전액조정 조건이면 원가를 150 늘려.'],'배부액 1,100 / 과소배부 150.',[
('예정원가 900, 예정시간 300, 작업 A 실제시간 40. A 배부액은?','120',['3','40','360'],'배부율 3×실제시간 40=120이야.'),('실제간접원가 500, 배부액 540. 차이는?','40 과대배부',['40 과소배부','500 과소배부','차이 없음'],'실제보다 40 더 배부했으므로 과대야.'),('과소배부 30을 매출원가에 전액 조정한다. 매출원가는?','30 증가',['30 감소','변화 없음','60 증가'],'실제보다 적게 배부한 원가를 더해.'),('제조간접원가의 실제배부율 분모는?','실제 배부기준 총량',['예정 매출액만','원재료 잔액','기말자본'],'실제총원가를 실제기준총량으로 나눠.')])

cost(17,[('직접배분법과 단계배분법의 숫자','직접배분법은 보조부문 간 상호 용역을 무시하고 제조부문 비율만 다시 합쳐 배분해. 보조부문 S 원가 90, 이용량이 다른 보조부문 20, 제조 A 30, B 60이면 A에 30, B에 60을 배분해.\n단계배분법은 정한 순서대로 아직 닫지 않은 부문에 배분해. 앞서 배분을 마친 부문으로 다시 배분하지 않으므로 순서가 결과에 영향을 줄 수 있어.'),('상호배분법은 연립식으로','보조 S의 자체원가 90, T의 자체원가 80, T가 S에 용역 10%, S가 T에 20%를 제공한다면 S=90+0.1T, T=80+0.2S로 총원가를 표현해. 서로 받은 원가까지 원가에 포함하는 거야.\n대입하면 S=98+0.02S, 따라서 0.98S=98, S=100이고 T=100이야. 제조부문에 나가는 몫은 S의 80%인 80과 T의 90%인 90으로 총 170, 자체원가 90+80과 같아.'),('제조부문에서 제품까지','보조부문 배분을 마치면 제조부문 자체원가와 받은 원가를 합쳐 제조부문 총원가를 구해. 그다음 각 제조부문에 적합한 기준으로 작업·제품에 배부해.\n부문 원가를 나누는 단계와 제품 원가를 나누는 단계는 서로 이어지지만 별도의 배분이야. 문제에서 어느 단계의 금액을 묻는지 확인해.')],
'보조부문 S 원가 120, 다른 보조부문 이용 20시간, 제조 A 이용 30시간, B 이용 50시간이야. 직접배분법 A 배분액은?',
['직접배분법은 보조부문끼리의 이용 20시간을 분모에서 제외해.','제조부문 총이용량=30+50=80시간이야.','A는 120×30/80=45, B는 120×50/80=75. 합계 120이야.'],'A 45 / B 75.',[
('보조원가 60, 제조 A 이용 20, B 이용 40, 타 보조 이용 40. 직접법 A 배분액은?','20',['12','24','40'],'60×20/(20+40)=20이야.'),('단계배분법에서 이미 배분을 마친 보조부문은?','후속 배분에서 다시 받지 않는다',['항상 다시 받는다','원가가 전부 사라진다','제품으로 표시한다'],'정해진 순서로 한 번씩 닫아가는 방법이야.'),('S=90+0.1T, T=80+0.2S이면 S는?','100',['90','98','110'],'대입해 0.98S=98이므로 100이야.'),('제조부문 자체원가 200, 보조부문에서 받은 원가 50. 제품배부 전 총원가는?','250',['150','200','50'],'자체원가와 배분받은 원가를 더해 250이야.')])

cost(18,[('작업원가표의 세 칸','작업 A의 직접재료·직접노무를 직접 추적하고 제조간접원가를 배부해 합계 원가를 구해. 직접노무원가의 150%를 간접원가로 배부한다면 노무 40일 때 간접 60이야.\n작업이 미완성이면 재공품, 완성되면 제품, 판매되면 매출원가로 옮겨. 작업원가표와 총계정원장의 원가흐름이 서로 맞는지 확인해.'),('기초 재공품과 당기 추가원가','기초에 이미 진행 중인 작업에는 전기까지 집계한 원가가 들어 있어. 당기 추가원가만으로 완성작업 총원가를 계산하면 기초원가를 누락할 수 있어.\n작업별 기초원가+당기 직접재료+당기 직접노무+배부 간접원가를 계산한 뒤 완성·판매 상태에 따라 나눠. 주문별 수량이 다르면 총원가와 개당 원가도 구분해.')],
'작업 A는 기초원가 20, 당기 재료 30, 노무 10, 간접배부 15로 완성했어. 작업 B는 총원가 50으로 미완성이야. A 5개 중 3개 판매했다면?',
['완성한 A의 총원가=20+30+10+15=75, 단위원가=75÷5=15야.','A 판매 3개 원가=45, 남은 제품 2개 원가=30이야.','미완성 B 원가 50은 기말재공품에 남아. 재공품과 완성품 재고를 섞지 않아.'],'매출원가 45 / 제품 30 / 재공품 50.',[
('작업 기초원가 10, 당기 재료 20, 노무 15, 배부간접 5. 완성원가는?','50',['40','35','25'],'10+20+15+5=50이야.'),('총작업원가 90으로 30개 완성. 단위원가는?','3',['30','90','2,700'],'작업 전체 원가 90을 그 작업에서 완성한 제품 30개에 나눠. 제품 한 개에 배분된 원가는 3이고, 3×30으로 총원가 90을 다시 확인할 수 있어.'),('직접노무 40의 150%를 간접원가로 배부. 간접배부액은?','60',['40','100','150'],'직접노무원가가 배부 기준이고 150%는 기준금액의 1.5배라는 뜻이야. 40×1.5=60을 제조간접원가로 배부해. 작업 총원가라면 직접노무 40 등 다른 요소도 더해야 해.'),('미완성 작업 A 20, B 35, 완성 미판매 C 40. 기말재공품은?','55',['95','40','60'],'미완성 A+B=55만 재공품이야.')])

cost(19,[('평균법 계산을 끝까지','평균법은 기초재공품 원가와 당기 투입원가를 합쳐 계산해. 완성품 환산량은 완성품 수량+기말재공품 수량×완성도야. 재료와 가공의 완성도를 따로 써.\n재료가 공정 초기에 전량 투입되고 완성품 80개, 기말재공품 20개·가공완성도 50%라면 재료 환산량 100개, 가공 환산량 90개야. 재료원가 1,000, 가공원가 900이면 각 환산단가는 10이야.'),('완성품과 기말재공품에 나눠','앞 사례의 완성품 원가는 80×(재료단가10+가공단가10)=1,600이야. 기말재공품은 재료 20×10=200, 가공 20×50%×10=100으로 총 300이야.\n1,600+300=총원가 1,900인지 확인해. 모든 원가가 완성품 또는 재공품에 배분됐는지 확인하는 합계 검산은 계산 실수를 잡아줘.'),('선입선출법은 당기 작업량만','기초재공품에 이미 완료한 작업량은 당기의 환산량에서 제외해. 기초 20개·가공 40%, 당기착수 80개, 완성 80개, 기말 20개·가공 50%라면 가공 환산량은 기초완성 20×60%+당기착수완성 60+기말 20×50%=82야.\n공정초기 재료 전량 투입이면 기초재공품에는 당기 추가재료가 필요 없다는 조건이야. 재료 환산량은 당기착수완성 60+기말 20=80이야. 당기원가를 이 당기환산량으로 나눠 단가를 구해.'),('기초원가를 완성품에 더해','선입선출법에서는 기초재공품의 전기원가를 별도로 가지고 와. 완성품 원가는 기초원가+기초를 완성하는 데 든 당기원가+당기착수완성 원가야.\n평균법과 달리 기초원가를 당기환산량의 단가 분자에 섞지 않아. 두 방법을 비교할 때 수량흐름은 같아도 원가를 섞는 방식이 다르다는 점을 기억해.'),('공손·감손과 검사 시점','공손품은 품질 불량 등으로 정상제품이 되지 못한 수량을 뜻해. 정상공손 원가는 일반적으로 적절한 양품 등에 부담시키고, 비정상공손은 기간손실로 구분해. 구체적인 배분은 검사시점과 원가계산 가정에 따라 달라져.\n공정 말에 검사하는데 기말재공품은 검사점을 지나지 않았다면 정상공손원가를 기말재공품에 부담시키지 않는 조건이 나올 수 있어. 무조건 전체수량에 같은 비율을 적용하지 말고 검사점 통과 여부를 표시해.')],
'평균법, 재료는 공정 초 전량 투입. 완성 80개, 기말재공품 20개·가공완성도 50%. 기초와 당기 합산 재료원가 1,000, 가공원가 900. 배분 결과는?',
['재료 환산량 80+20=100, 가공 환산량 80+20×50%=90이야.','각 단가는 재료 1,000÷100=10, 가공 900÷90=10이야.','완성품 80×20=1,600, 기말재공품 20×10+10×10=300. 총액 1,900으로 맞아.'],'완성품원가 1,600 / 기말재공품원가 300.',[
('평균법 완성 100개, 기말 40개·가공완성도 25%. 가공 환산량은?','110개',['140개','100개','35개'],'100+40×25%=110개야.'),('FIFO 기초 20개·가공 40%, 당기착수완성 60개, 기말 20개·가공 50%. 당기 가공 환산량은?','82개',['90개','100개','72개'],'20×60%+60+20×50%=82개야.'),('평균법 재료원가 600, 재료 환산량 120개. 단위당 재료원가는?','5',['120','600','72,000'],'평균법에서는 기초와 당기의 재료원가를 합한 600을 재료 완성품환산량 120으로 나눠. 재료 환산량 한 단위당 5이며 가공원가 단가는 별도로 계산해.'),('비정상공손 원가는 일반적으로?','기간손실',['항상 양품 원가에 모두 포함','항상 자본금','무조건 기말재료'],'정상공손과 구분하여 기간손실로 처리해.')])

cost(20,[('물량과 판매가치의 분모','결합제품은 분리점 전 공통 원가를 제품별로 직접 추적하기 어려워 합리적인 기준으로 배분해. 물량법은 비교가능한 수량·중량 비율, 상대판매가치법은 분리점의 총판매가치 비율을 써.\n단가 비율만 쓰지 말고 단가×수량으로 제품별 전체 판매가치를 구해. kg과 리터처럼 단위가 다른 물량을 그대로 합치는 것도 피해야 해.'),('순실현가능가치법','분리점 시장가격이 없고 추가가공 후에만 팔 수 있다면 최종판매가치에서 분리 후 추가가공원가 등을 빼 분리점의 상대가치를 추정할 수 있어. 그 순실현가능가치 비율로 공통원가를 배분해.\n최종판매가치 A 200, B 150, 추가가공 A 50, B 50이면 배분기준은 150:100이야. A가 더 많은 추가가공을 한다는 사실을 그대로 무시하지 않아.'),('부산물과 추가가공 결정','주산물에 비해 상대적으로 가치가 낮은 부산물은 문제에서 지정한 원가 차감 또는 수익 처리 등의 방법을 따라. 모든 부산물을 주산물과 똑같이 복잡하게 배분하는 것은 아니야.\n분리점 뒤 추가가공 여부는 추가판매수익과 추가가공원가를 비교해. 이미 발생한 결합원가는 그 결정으로 바뀌지 않으므로 배분받았다는 이유만으로 다시 추가원가에 포함하지 않아.')],
'결합원가 100, 최종판매가치 A 200·B 150, 분리 후 가공원가 A 50·B 50이야. 순실현가능가치법의 배분액은?',
['A 기준금액=200−50=150, B=150−50=100이야.','총기준금액 250이므로 A=100×150/250=60, B=100×100/250=40이야.','배분 60+40=100 확인. 총제품원가를 물으면 각각 추가가공원가를 다시 더해 A110, B90이야.'],'결합원가 배분 A 60 / B 40.',[
('결합원가 120, A 판매가치 300, B 100. 상대판매가치법 A 배분액은?','90',['30','120','300'],'120×300/(300+100)=90이야.'),('최종판매가치 200, 분리 후 원가 50. NRV법 배분기준금액은?','150',['250','200','50'],'최종가치에서 추가가공원가를 빼 150이야.'),('분리점 판매 80, 추가가공 후 120, 추가가공원가 25. 추가가공의 이익 증가액은?','15',['40','25','95'],'추가수익 120−80=40에서 추가원가25를 빼 15야.'),('추가가공 의사결정 시 이미 발생한 결합원가는?','일반적으로 매몰원가',['항상 추가원가','항상 기회원가','매출채권'],'어느 대안을 택해도 이미 발생한 원가는 바뀌지 않아.')])

